coalesce_chr <- function(x, fallback = "") {
  if (is.null(x) || length(x) == 0 || is.na(x) || !nzchar(as.character(x))) {
    fallback
  } else {
    as.character(x)
  }
}

get_run_metric_value <- function(run_data, metric, default = "") {
  if (is.null(run_data) || !is.data.frame(run_data) || !all(c("Metric", "Value") %in% names(run_data))) {
    return(default)
  }
  idx <- which(as.character(run_data$Metric) == metric)
  if (length(idx) == 0) return(default)
  value <- as.character(run_data$Value[idx[1]])
  if (!nzchar(value) || identical(value, "NA")) return(default)
  value
}

resolve_historical_target_draft_label <- function(x) {
  val <- trimws(as.character(x %||% ""))
  if (!nzchar(val)) return("")

  lower <- tolower(val)
  if (lower %in% tolower(unname(historical_target_draft_by_id))) {
    return(unname(historical_target_draft_by_id)[match(lower, tolower(unname(historical_target_draft_by_id)))])
  }

  if (val %in% names(historical_target_draft_by_id)) {
    return(unname(historical_target_draft_by_id[[val]]))
  }

  id_guess <- gsub("(?i)^draft\\s*type\\s*", "", val, perl = TRUE)
  id_guess <- trimws(id_guess)
  if (id_guess %in% names(historical_target_draft_by_id)) {
    return(unname(historical_target_draft_by_id[[id_guess]]))
  }

  if (val %in% names(adp_draft_type_choices)) {
    adp_id <- unname(adp_draft_type_choices[[val]])
    if (adp_id %in% names(historical_target_draft_by_id)) {
      return(unname(historical_target_draft_by_id[[adp_id]]))
    }
  }

  ""
}

col_or_na <- function(df, name_options) {
  if (is.null(df) || !is.data.frame(df) || nrow(df) == 0) {
    return(character(0))
  }
  hit <- intersect(name_options, names(df))
  if (length(hit) == 0) {
    return(rep(NA, nrow(df)))
  }
  df[[hit[1]]]
}

make_player_key <- function(name, team = "") {
  paste0(
    tolower(trimws(as.character(name))),
    "|",
    toupper(trimws(as.character(team)))
  )
}

as_int_safe <- function(x, default = 0L) {
  if (is.null(x) || length(x) == 0) return(as.integer(default))
  out <- suppressWarnings(as.integer(x))
  if (length(out) == 0 || is.na(out[1])) return(as.integer(default))
  as.integer(out[1])
}

as_num_safe <- function(x, default = NA_real_) {
  if (is.null(x) || length(x) == 0) return(default)
  out <- suppressWarnings(as.numeric(x))
  if (length(out) == 0 || is.na(out[1])) return(default)
  out[1]
}

compute_snake_overall_pick <- function(round_value, league_teams, draft_position) {
  rd <- suppressWarnings(as.integer(round_value))
  tm <- suppressWarnings(as.integer(league_teams))
  pos <- suppressWarnings(as.integer(draft_position))
  if (any(is.na(c(rd, tm, pos)))) return(NA_real_)
  if (rd < 1L || tm < 2L || pos < 1L || pos > tm) return(NA_real_)
  pick_in_round <- if ((rd %% 2L) == 1L) pos else (tm - pos + 1L)
  as.numeric((rd - 1L) * tm + pick_in_round)
}

normalize_selected_hitter_categories <- function(categories) {
  out <- unique(tolower(trimws(as.character(categories %||% character(0)))))
  out <- out[nzchar(out)]
  out[out %in% unname(hitter_category_choices)]
}

get_selected_hitter_metric_columns <- function(dat_names, selected_categories) {
  if (is.null(dat_names) || length(dat_names) == 0) return(character(0))
  selected_categories <- normalize_selected_hitter_categories(selected_categories)
  if (length(selected_categories) == 0) return(character(0))

  proj_map <- c(
    pa = "pa",
    hr = "hr",
    sb = "sb",
    avg = "avg",
    r = "r",
    rbi = "rbi",
    obp = "obp"
  )
  z_map <- c(
    pa = "pa_z",
    hr = "hr_z",
    sb = "sb_z",
    avg = "avg_z",
    r = "r_z",
    rbi = "rbi_z",
    obp = "obp_z"
  )

  list(
    proj = intersect(unname(proj_map[selected_categories]), dat_names),
    z = intersect(unname(z_map[selected_categories]), dat_names)
  )
}

revalue_hitter_output <- function(
  dat,
  selected_categories,
  stat_weights,
  pa_weight = 0,
  z_source = NULL,
  num_teams,
  total_budget,
  hitter_budget_share,
  min_bid,
  starter_slots_per_team
) {
  if (is.null(dat) || !is.data.frame(dat) || nrow(dat) == 0) {
    return(dat)
  }

  z_map <- c(
    pa = "pa_z",
    hr = "hr_z",
    sb = "sb_z",
    avg = "avg_z",
    r = "r_z",
    rbi = "rbi_z",
    obp = "obp_z"
  )

  selected_categories <- normalize_selected_hitter_categories(selected_categories)
  selected_categories <- selected_categories[selected_categories %in% names(z_map)]
  if (length(selected_categories) == 0) {
    return(dat)
  }

  # Prefer non-starter z columns from z_source (z_hr, z_sb, ...), because
  # displayed *_z columns are starter-normalized and break dollar denominators.
  out_name <- as.character(col_or_na(dat, c("player_name", "name", "Name")))
  out_team <- as.character(col_or_na(dat, c("team", "Team")))
  out_key <- make_player_key(out_name, out_team)

  z_map_output <- c(
    pa = "pa_z",
    hr = "hr_z",
    sb = "sb_z",
    avg = "avg_z",
    r = "r_z",
    rbi = "rbi_z",
    obp = "obp_z"
  )
  z_map_source <- c(
    pa = "z_pa",
    hr = "z_hr",
    sb = "z_sb",
    avg = "z_avg",
    r = "z_r",
    rbi = "z_rbi",
    obp = "z_obp"
  )

  z_cols_by_cat <- setNames(vector("list", length(selected_categories)), selected_categories)
  names(z_cols_by_cat) <- selected_categories
  for (cat_key in selected_categories) {
    z_cols_by_cat[[cat_key]] <- rep(NA_real_, nrow(dat))
  }

  if (!is.null(z_source) && is.data.frame(z_source) && nrow(z_source) > 0) {
    src_name <- as.character(col_or_na(z_source, c("player_name", "name", "Name")))
    src_team <- as.character(col_or_na(z_source, c("team", "Team")))
    src_key <- make_player_key(src_name, src_team)
    src_idx <- match(out_key, src_key)
    for (cat_key in selected_categories) {
      src_col <- z_map_source[[cat_key]]
      if (!is.null(src_col) && src_col %in% names(z_source)) {
        vals <- suppressWarnings(as.numeric(z_source[[src_col]]))
        hit <- !is.na(src_idx)
        z_cols_by_cat[[cat_key]][hit] <- vals[src_idx[hit]]
      }
    }
  }

  # Fallback to displayed columns when source z columns are unavailable.
  for (cat_key in selected_categories) {
    miss <- !is.finite(z_cols_by_cat[[cat_key]])
    out_col <- z_map_output[[cat_key]]
    if (any(miss) && !is.null(out_col) && out_col %in% names(dat)) {
      fallback_vals <- suppressWarnings(as.numeric(dat[[out_col]]))
      z_cols_by_cat[[cat_key]][miss] <- fallback_vals[miss]
    }
  }

  z_df <- as.data.frame(z_cols_by_cat, check.names = FALSE, stringsAsFactors = FALSE)
  z_mat <- as.matrix(z_df)
  pa_z <- rep(NA_real_, nrow(dat))
  if (!is.null(z_source) && is.data.frame(z_source) && nrow(z_source) > 0 && "z_pa" %in% names(z_source)) {
    src_name <- as.character(col_or_na(z_source, c("player_name", "name", "Name")))
    src_team <- as.character(col_or_na(z_source, c("team", "Team")))
    src_key <- make_player_key(src_name, src_team)
    src_idx <- match(out_key, src_key)
    pa_vals <- suppressWarnings(as.numeric(z_source$z_pa))
    hit <- !is.na(src_idx)
    pa_z[hit] <- pa_vals[src_idx[hit]]
  }
  pa_missing <- !is.finite(pa_z)
  if (any(pa_missing) && "pa_z" %in% names(dat)) {
    pa_fallback <- suppressWarnings(as.numeric(dat$pa_z))
    pa_z[pa_missing] <- pa_fallback[pa_missing]
  }

  raw_mat <- cbind(pa_z, z_mat)
  z_total_raw <- rowSums(raw_mat, na.rm = TRUE)
  z_total_raw[rowSums(is.finite(raw_mat)) == 0] <- NA_real_

  if (is.null(stat_weights) || !length(stat_weights)) {
    stat_weights <- setNames(rep(1, length(selected_categories)), selected_categories)
  }
  weights_selected <- suppressWarnings(as.numeric(stat_weights[selected_categories]))
  weights_selected[!is.finite(weights_selected)] <- 0
  pa_weight <- suppressWarnings(as.numeric(pa_weight))
  if (!is.finite(pa_weight)) pa_weight <- 0
  if (all(weights_selected == 0) && pa_weight == 0) {
    z_total_weights <- z_total_raw
  } else {
    w_mat <- sweep(z_mat, 2, weights_selected, FUN = "*")
    custom_mat <- cbind(pa_z * pa_weight, w_mat)
    z_total_weights <- rowSums(custom_mat, na.rm = TRUE)
    z_total_weights[rowSums(is.finite(custom_mat)) == 0] <- NA_real_
  }

  n_rows <- nrow(dat)
  teams_n <- suppressWarnings(as.integer(num_teams))
  if (!is.finite(teams_n) || is.na(teams_n) || teams_n <= 0) {
    teams_n <- 12L
  }
  starter_slots <- suppressWarnings(as.numeric(starter_slots_per_team))
  if (!is.finite(starter_slots) || starter_slots <= 0) {
    starter_slots <- 14
  }
  starter_count <- as.integer(max(1L, round(teams_n * starter_slots)))
  starter_count <- min(starter_count, n_rows)

  adp_vec <- suppressWarnings(as.numeric(col_or_na(dat, c("adp", "ADP"))))
  name_vec <- as.character(col_or_na(dat, c("player_name", "name", "Name")))
  starter_order <- order(-z_total_weights, adp_vec, name_vec, na.last = TRUE)
  starter_idx <- starter_order[seq_len(starter_count)]

  budget_bats <- as_num_safe(total_budget, 260) * as_num_safe(hitter_budget_share, 0.70) * as_num_safe(num_teams, 12)
  min_bid_val <- as_num_safe(min_bid, 1)

  z_replacement_raw <- min(z_total_raw[starter_idx], na.rm = TRUE)
  z_above_repl_raw <- sum(z_total_raw[starter_idx] - z_replacement_raw, na.rm = TRUE)

  z_replacement_weights <- min(z_total_weights[starter_idx], na.rm = TRUE)
  z_above_repl_weights <- sum(z_total_weights[starter_idx] - z_replacement_weights, na.rm = TRUE)

  dollar_formula <- function(z_value, z_repl, z_above_total) {
    if (!is.finite(z_above_total) || z_above_total <= 0) {
      return(rep(NA_real_, length(z_value)))
    }
    dollars_per_z <- (budget_bats - starter_count * min_bid_val) / z_above_total
    pmax((z_value - z_repl) * dollars_per_z + min_bid_val, min_bid_val)
  }

  dollars_raw <- dollar_formula(z_total_raw, z_replacement_raw, z_above_repl_raw)
  dollars_weights <- dollar_formula(z_total_weights, z_replacement_weights, z_above_repl_weights)

  out <- dat
  out$z_total_raw <- round(z_total_raw, 3)
  out$z_total_weights <- round(z_total_weights, 3)
  out$dollars_raw <- round(dollars_raw, 2)
  out$dollars_weights <- round(dollars_weights, 2)

  out <- out[order(-out$dollars_weights, adp_vec, name_vec, na.last = TRUE), , drop = FALSE]
  rownames(out) <- NULL
  out
}

read_cached_hitter_zscores <- function(cfg, season) {
  path <- file.path(cfg$paths$processed_dir, sprintf("%s_hitters_weighted_per_pa_zscores.csv", season))
  if (!file.exists(path)) return(NULL)
  tryCatch(
    utils::read.csv(path, stringsAsFactors = FALSE, check.names = FALSE),
    error = function(e) NULL
  )
}

