ensure_selected_choice <- function(choices, selected_value) {
  selected_value <- trimws(as.character(selected_value %||% ""))
  if (!nzchar(selected_value)) {
    return(choices)
  }
  if (selected_value %in% as.character(unname(choices))) {
    return(choices)
  }
  c(stats::setNames(selected_value, selected_value), choices)
}

normalize_team_token <- function(team_token) {
  tm <- trimws(as.character(team_token %||% ""))
  if (!nzchar(tm)) return("")
  tm_key <- toupper(normalize_team_abbrev(tm))
  if (!nzchar(tm_key) || identical(tm_key, "NA")) {
    return(toupper(tm))
  }
  tm_key
}

make_dropdown_labels <- function(player_name, team) {
  nm <- trimws(as.character(player_name %||% ""))
  tm <- trimws(as.character(team %||% ""))
  if (length(nm) == 0L) return(character(0))
  name_key <- normalize_join_name(nm)
  dup_name <- duplicated(name_key) | duplicated(name_key, fromLast = TRUE)
  ifelse(dup_name & nzchar(tm), sprintf("%s (%s)", nm, tm), nm)
}

parse_manual_player_entry <- function(raw_value) {
  val <- trimws(as.character(raw_value %||% ""))
  if (!nzchar(val)) {
    return(list(name = "", team = ""))
  }

  # "First Last|TEAM" or label-like strings that include pipes.
  if (grepl("|", val, fixed = TRUE)) {
    parts <- trimws(unlist(strsplit(val, "|", fixed = TRUE)))
    parts <- parts[nzchar(parts)]
    if (length(parts) > 0) {
      name_part <- parts[1]
      team_part <- ""
      m <- regexec("^(.*)\\(([A-Za-z]{2,3})\\)\\s*$", name_part, perl = TRUE)
      g <- regmatches(name_part, m)[[1]]
      if (length(g) == 3) {
        name_part <- trimws(g[2])
        team_part <- g[3]
      } else if (length(parts) >= 2 && grepl("^[A-Za-z]{2,3}$", parts[2])) {
        team_part <- parts[2]
      } else if (length(parts) >= 1 && grepl("^[A-Za-z]{2,3}$", parts[length(parts)])) {
        team_part <- parts[length(parts)]
      }
      return(list(name = trimws(name_part), team = normalize_team_token(team_part)))
    }
  }

  # "First Last (TEAM)"
  m <- regexec("^(.*)\\(([A-Za-z]{2,3})\\)\\s*$", val, perl = TRUE)
  g <- regmatches(val, m)[[1]]
  if (length(g) == 3) {
    return(list(name = trimws(g[2]), team = normalize_team_token(g[3])))
  }

  # "First LastTEAM" fallback when user appends team at end.
  m2 <- regexec("^(.*?)([A-Z]{2,3})$", val, perl = TRUE)
  g2 <- regmatches(val, m2)[[1]]
  if (length(g2) == 3 && nzchar(trimws(g2[2]))) {
    return(list(name = trimws(g2[2]), team = normalize_team_token(g2[3])))
  }

  list(name = trimws(val), team = "")
}

resolve_player_key <- function(raw_value, lookup_df) {
  val <- trimws(as.character(raw_value %||% ""))
  if (!nzchar(val)) return("")
  if (is.null(lookup_df) || !is.data.frame(lookup_df) || nrow(lookup_df) == 0) return("")

  keys <- as.character(lookup_df$key %||% character(0))
  if (val %in% keys) return(val)

  player <- tolower(trimws(as.character(lookup_df$player_name %||% rep("", nrow(lookup_df)))))
  team <- toupper(trimws(as.character(lookup_df$team %||% rep("", nrow(lookup_df)))))
  team_norm <- toupper(normalize_team_abbrev(team))
  name_norm <- normalize_join_name(player)
  adp <- suppressWarnings(as.numeric(lookup_df$adp %||% rep(NA_real_, nrow(lookup_df))))

  norm_val <- tolower(val)
  label_name_team <- tolower(trimws(sprintf("%s (%s)", player, team)))
  idx <- which(player == norm_val | label_name_team == norm_val)

  # Support typed key patterns with team aliases, e.g. "Matt Chapman|SF".
  if (length(idx) == 0L && grepl("|", val, fixed = TRUE)) {
    parsed <- parse_manual_player_entry(val)
    if (nzchar(parsed$name)) {
      nm <- normalize_join_name(parsed$name)
      if (nzchar(parsed$team)) {
        tm <- normalize_team_token(parsed$team)
        idx <- which(name_norm == nm & team_norm == tm)
        # Team codes can drift during offseason moves; fall back to name-only.
        if (length(idx) == 0L) {
          idx <- which(name_norm == nm)
        }
      } else {
        idx <- which(name_norm == nm)
      }
    }
  }

  if (length(idx) == 0L) {
    m <- regexec("^(.+)\\s*\\(([A-Za-z]{2,3})\\)$", val)
    g <- regmatches(val, m)[[1]]
    if (length(g) == 3) {
      nm <- normalize_join_name(g[2])
      tm <- normalize_team_token(g[3])
      idx <- which(name_norm == nm & team_norm == tm)
    }
  }

  if (length(idx) == 0L) {
    nm <- normalize_join_name(val)
    idx <- which(name_norm == nm)
  }

  if (length(idx) == 0L) {
    idx <- which(startsWith(player, norm_val) | startsWith(name_norm, normalize_join_name(val)))
  }

  if (length(idx) == 0L) return("")
  if (length(idx) == 1L) return(as.character(lookup_df$key[idx]))

  ord <- order(adp[idx], player[idx], na.last = TRUE)
  as.character(lookup_df$key[idx[ord[1]]])
}

