read_pitcher_rp_supplement <- function(cfg, season, adp_keys) {
  # Read raw pitcher projections (Steamer preferred, then oopsy) to get RP stats
  # Only returns pitchers that are in adp_keys so we don't flood the list
  raw_dir <- cfg$paths$raw_dir
  systems <- c("steamer", "oopsy", "thebat", "atc")
  raw <- NULL
  for (sys in systems) {
    json_path <- file.path(raw_dir, sprintf("%s_%s_pitchers_raw.json", as.integer(season), sys))
    if (file.exists(json_path)) {
      raw <- tryCatch(
        jsonlite::fromJSON(json_path, simplifyDataFrame = TRUE),
        error = function(e) NULL
      )
      if (!is.null(raw) && is.data.frame(raw) && nrow(raw) > 0) break
      if (!is.null(raw) && is.list(raw) && "data" %in% names(raw)) {
        raw <- tryCatch(as.data.frame(raw$data, stringsAsFactors = FALSE), error = function(e) NULL)
        if (!is.null(raw) && nrow(raw) > 0) break
      }
      raw <- NULL
    }
  }
  if (is.null(raw) || !is.data.frame(raw) || nrow(raw) == 0) return(NULL)

  col <- function(opts) {
    hit <- intersect(opts, names(raw))
    if (length(hit) == 0) return(rep(NA_character_, nrow(raw)))
    as.character(raw[[hit[1]]])
  }
  num <- function(opts) suppressWarnings(as.numeric(col(opts)))

  out <- data.frame(
    player_name = col(c("PlayerName", "player_name", "Name", "name")),
    team        = col(c("Team", "team")),
    adp         = num(c("ADP", "adp")),
    proj_ip     = num(c("IP", "proj_ip")),
    proj_w      = num(c("W", "proj_w")),
    proj_k      = num(c("SO", "K", "proj_k")),
    proj_sv     = num(c("SV", "proj_sv")),
    proj_era    = num(c("ERA", "proj_era")),
    proj_whip   = num(c("WHIP", "proj_whip")),
    proj_gs     = num(c("GS", "proj_gs")),
    stringsAsFactors = FALSE
  )

  # Keep only pure relievers (GS < 5) with a real player name
  out <- out[!is.na(out$player_name) & nzchar(trimws(out$player_name)), , drop = FALSE]
  gs <- suppressWarnings(as.numeric(out$proj_gs))
  out <- out[is.na(gs) | gs < 5, , drop = FALSE]

  out$key <- make_player_key(out$player_name, out$team)
  out <- out[!duplicated(out$key), , drop = FALSE]

  # Restrict to pitchers who appear in the ADP data (have been drafted).
  # Use normalize_join_name for accent-insensitive, team-agnostic matching.
  if (length(adp_keys) > 0) {
    adp_names_norm <- normalize_join_name(sub("\\|.*$", "", adp_keys))
    out_names_norm <- normalize_join_name(out$player_name)
    out <- out[out_names_norm %in% adp_names_norm, , drop = FALSE]
  }

  out$proj_gs <- NULL
  rownames(out) <- NULL
  out
}

