read_cached_historical_targets <- function(cfg) {
  path <- file.path(cfg$paths$processed_dir, "2025_historical_targets_80th.csv")
  if (!file.exists(path)) {
    return(historical_target_defaults)
  }
  dat <- tryCatch(
    utils::read.csv(path, stringsAsFactors = FALSE, check.names = FALSE),
    error = function(e) NULL
  )
  if (is.null(dat) || !is.data.frame(dat) || nrow(dat) == 0) {
    return(historical_target_defaults)
  }

  draft_col <- intersect(c("Draft.Type", "Draft Type", "draft_type"), names(dat))
  if (length(draft_col) == 0) {
    return(historical_target_defaults)
  }
  names(dat)[names(dat) == draft_col[1]] <- "Draft.Type"
  dat$Draft.Type <- trimws(as.character(dat$Draft.Type))
  keep_cols <- intersect(names(historical_target_defaults), names(dat))
  if (length(keep_cols) == ncol(historical_target_defaults)) {
    dat <- dat[, names(historical_target_defaults), drop = FALSE]
  }
  dat$Draft.Type <- trimws(as.character(dat$Draft.Type))
  dat <- dat[nzchar(dat$Draft.Type), , drop = FALSE]

  missing_labels <- setdiff(historical_target_defaults$Draft.Type, dat$Draft.Type)
  if (length(missing_labels) > 0) {
    dat <- rbind(dat, historical_target_defaults[historical_target_defaults$Draft.Type %in% missing_labels, , drop = FALSE])
  }
  rownames(dat) <- NULL
  dat
}

read_cached_atc_hitter_reference <- function(cfg, season) {
  path <- file.path(cfg$paths$processed_dir, sprintf("%s_atc_hitters_standard.csv", as.integer(season)))
  if (!file.exists(path)) {
    return(NULL)
  }
  dat <- tryCatch(
    utils::read.csv(path, stringsAsFactors = FALSE, check.names = FALSE),
    error = function(e) NULL
  )
  if (is.null(dat) || !is.data.frame(dat) || nrow(dat) == 0) {
    return(NULL)
  }

  name_col <- intersect(c("name", "player_name", "Name"), names(dat))
  team_col <- intersect(c("team", "Team"), names(dat))
  ab_col <- intersect(c("ab", "AB"), names(dat))
  h_col <- intersect(c("h", "H"), names(dat))
  pa_col <- intersect(c("pa", "PA"), names(dat))
  if (length(name_col) == 0 || length(ab_col) == 0) {
    return(NULL)
  }

  out <- data.frame(
    player_name = as.character(dat[[name_col[1]]]),
    team = if (length(team_col) > 0) as.character(dat[[team_col[1]]]) else "",
    ab = suppressWarnings(as.numeric(dat[[ab_col[1]]])),
    h = if (length(h_col) > 0) suppressWarnings(as.numeric(dat[[h_col[1]]])) else NA_real_,
    pa = if (length(pa_col) > 0) suppressWarnings(as.numeric(dat[[pa_col[1]]])) else NA_real_,
    stringsAsFactors = FALSE
  )
  out$key <- make_player_key(out$player_name, out$team)
  out$name_key <- normalize_join_name(out$player_name)
  out <- out[order(-out$pa, -out$ab, out$player_name, na.last = TRUE), , drop = FALSE]
  out <- out[!duplicated(out$key), , drop = FALSE]
  out_name <- out[!duplicated(out$name_key), , drop = FALSE]
  rownames(out) <- NULL
  rownames(out_name) <- NULL
  list(by_key = out, by_name = out_name)
}

extract_position_tokens <- function(x) {
  x <- toupper(gsub("\\s+", "", as.character(x)))
  x[is.na(x)] <- ""
  lapply(strsplit(x, "[,/;|]"), function(parts) {
    parts <- trimws(parts)
    unique(parts[nzchar(parts)])
  })
}

row_has_any_position <- function(position_strings, selected_positions) {
  if (length(selected_positions) == 0) {
    return(rep(TRUE, length(position_strings)))
  }
  selected_positions <- unique(toupper(as.character(selected_positions)))
  tokens <- extract_position_tokens(position_strings)

  is_hitter_only_ut <- function(tok) {
    hitter_base <- c("C", "1B", "2B", "3B", "SS", "OF", "UT")
    hitter_tok <- tok[tok %in% hitter_base]
    "UT" %in% hitter_tok && all(hitter_tok %in% "UT")
  }

  row_matches <- function(tok) {
    checks <- logical(0)
    if ("ALL_HITTERS" %in% selected_positions) {
      checks <- c(checks, any(tok %in% c("C", "1B", "2B", "3B", "SS", "OF", "UT")))
    }
    if ("CI" %in% selected_positions) {
      checks <- c(checks, any(tok %in% c("1B", "3B")))
    }
    if ("MI" %in% selected_positions) {
      checks <- c(checks, any(tok %in% c("2B", "SS")))
    }
    if ("P" %in% selected_positions) {
      checks <- c(checks, any(tok %in% c("P", "SP", "RP")))
    }

    base_selected <- setdiff(selected_positions, c("ALL_HITTERS", "CI", "MI", "P"))
    if (length(base_selected) > 0) {
      base_hits <- vapply(base_selected, function(sel) {
        if (identical(sel, "UT")) {
          return(is_hitter_only_ut(tok))
        }
        sel %in% tok
      }, logical(1))
      checks <- c(checks, any(base_hits))
    }

    any(checks)
  }

  vapply(tokens, row_matches, logical(1))
}

fill_missing_hitter_positions <- function(dat, adp_dat = NULL) {
  if (is.null(dat) || !is.data.frame(dat) || nrow(dat) == 0) {
    return(dat)
  }

  pos_col <- intersect(c("position", "positions", "Position", "Position(s)"), names(dat))
  if (length(pos_col) == 0) {
    return(dat)
  }
  pos_col <- pos_col[1]

  out <- dat
  pos <- as.character(out[[pos_col]])
  pos[is.na(pos)] <- ""
  missing_pos <- !nzchar(trimws(pos))
  if (!any(missing_pos)) {
    return(out)
  }

  adp_tbl <- prepare_adp_table(adp_dat)
  if (!is.null(adp_tbl) && is.data.frame(adp_tbl) && nrow(adp_tbl) > 0) {
    out_name <- as.character(col_or_na(out, c("player_name", "name", "Name")))
    out_team <- as.character(col_or_na(out, c("team", "Team")))
    out_key <- make_player_key(out_name, out_team)

    adp_key <- make_player_key(adp_tbl$player_name, adp_tbl$team)
    key_idx <- match(out_key, adp_key)
    key_fill <- missing_pos & !is.na(key_idx)
    if (any(key_fill)) {
      key_positions <- trimws(as.character(adp_tbl$positions[key_idx[key_fill]]))
      has_pos <- nzchar(key_positions)
      idx_rows <- which(key_fill)
      pos[idx_rows[has_pos]] <- key_positions[has_pos]
    }

    missing_pos <- !nzchar(trimws(pos))
    if (any(missing_pos)) {
      name_key_out <- normalize_join_name(out_name)
      adp_name_key <- normalize_join_name(adp_tbl$player_name)
      adp_pos <- trimws(as.character(adp_tbl$positions))
      adp_pos[is.na(adp_pos)] <- ""

      adp_by_name <- tapply(adp_pos, adp_name_key, function(v) {
        vals <- unique(v[nzchar(v)])
        if (length(vals) == 1) vals[1] else NA_character_
      })
      name_fill <- unname(adp_by_name[name_key_out[missing_pos]])
      has_name_pos <- !is.na(name_fill) & nzchar(name_fill)
      if (any(has_name_pos)) {
        idx_rows <- which(missing_pos)
        pos[idx_rows[has_name_pos]] <- name_fill[has_name_pos]
      }
    }
  }

  pos[!nzchar(trimws(pos))] <- "UT"
  out[[pos_col]] <- pos
  out
}

pool_matches_hitter_slot <- function(position_strings, slot_code) {
  slot_code <- toupper(trimws(as.character(slot_code %||% "")))
  filters <- switch(
    slot_code,
    "C" = c("C"),
    "1B" = c("1B"),
    "2B" = c("2B"),
    "3B" = c("3B"),
    "SS" = c("SS"),
    "OF" = c("OF"),
    "MI" = c("MI"),
    "CI" = c("CI"),
    "IF" = c("C", "1B", "2B", "3B", "SS"),
    "UT" = adp_hitter_filter_set,
    adp_hitter_filter_set
  )
  row_has_any_position(position_strings, filters)
}

pool_matches_pitcher_slot <- function(position_strings, slot_code) {
  slot_code <- toupper(trimws(as.character(slot_code %||% "")))
  filters <- switch(
    slot_code,
    "SP" = c("SP", "P"),
    "RP" = c("RP", "P"),
    "P" = c("P"),
    c("P")
  )
  row_has_any_position(position_strings, filters)
}

add_pitcher_role_integrated <- function(dat) {
  if (is.null(dat) || !is.data.frame(dat) || nrow(dat) == 0) {
    return(dat)
  }
  sv <- suppressWarnings(as.numeric(dat$proj_sv))
  dat$pitcher_role <- ifelse(!is.na(sv) & sv >= 5, "RP", "SP")
  dat
}

add_pitcher_role_sp_skillz <- function(dat) {
  if (is.null(dat) || !is.data.frame(dat) || nrow(dat) == 0) {
    return(dat)
  }
  gs <- suppressWarnings(as.numeric(dat$gs))
  start_share <- suppressWarnings(as.numeric(dat$start_share))
  is_sp <- (!is.na(gs) & gs >= 5) | (!is.na(start_share) & start_share >= 0.5)
  dat$pitcher_role <- ifelse(is_sp, "SP", "RP")
  dat
}

resolve_existing_file <- function(paths) {
  paths <- as.character(paths %||% character(0))
  paths <- trimws(paths)
  paths <- paths[nzchar(paths)]
  if (length(paths) == 0) {
    return("")
  }
  hit <- paths[file.exists(paths)]
  if (length(hit) == 0) {
    return("")
  }
  hit[[1]]
}

run_pitcher_integration_system <- function(cfg_path, season, adp_tsv_path, system_name, raw_dir) {
  out_csv <- tempfile(pattern = paste0("pitcher_", system_name, "_"), fileext = ".csv")
  args <- c(
    "scripts/build_pitcher_integration_table.R",
    "--config", cfg_path,
    "--season", as.character(as.integer(season)),
    "--adp-tsv", adp_tsv_path,
    "--pitcher-system", as.character(system_name),
    "--no-sheet-export",
    "--out-csv", out_csv
  )

  raw_json <- file.path(raw_dir, sprintf("%s_%s_pitchers_raw.json", as.integer(season), as.character(system_name)))
  if (file.exists(raw_json)) {
    args <- c(args, "--projection-json", raw_json)
  }

  cmd <- tryCatch(
    system2("Rscript", args, stdout = TRUE, stderr = TRUE),
    error = function(e) e
  )

  if (inherits(cmd, "error")) {
    return(list(ok = FALSE, log = conditionMessage(cmd), data = NULL))
  }

  cmd_status <- attr(cmd, "status")
  if (!is.null(cmd_status) && as.integer(cmd_status) != 0) {
    return(list(ok = FALSE, log = paste(cmd, collapse = "\n"), data = NULL))
  }

  dat <- tryCatch(
    utils::read.csv(out_csv, stringsAsFactors = FALSE, check.names = FALSE),
    error = function(e) e
  )
  if (inherits(dat, "error") || !is.data.frame(dat) || nrow(dat) == 0) {
    msg <- if (inherits(dat, "error")) conditionMessage(dat) else "Output table empty."
    return(list(ok = FALSE, log = msg, data = NULL))
  }

  dat$key <- make_player_key(dat$player_name, dat$team)
  list(ok = TRUE, log = paste(cmd, collapse = "\n"), data = dat)
}

blend_pitcher_integration_outputs <- function(system_results, weights) {
  ok_systems <- names(system_results)
  if (length(ok_systems) == 0) {
    return(NULL)
  }

  row_counts <- vapply(system_results, function(x) nrow(x$data), integer(1))
  base_system <- ok_systems[[which.max(row_counts)]]
  out <- system_results[[base_system]]$data

  all_keys <- unique(unlist(lapply(system_results, function(x) x$data$key)))
  missing_keys <- setdiff(all_keys, out$key)
  if (length(missing_keys) > 0) {
    tmpl <- out[rep(1, length(missing_keys)), , drop = FALSE]
    tmpl[] <- NA
    tmpl$key <- missing_keys
    for (res in system_results) {
      idx <- match(missing_keys, res$data$key)
      hit <- !is.na(idx)
      if (any(hit)) {
        tmpl$player_name[hit] <- res$data$player_name[idx[hit]]
        tmpl$team[hit] <- res$data$team[idx[hit]]
      }
    }
    out <- rbind(out, tmpl)
  }

  proj_cols <- intersect(c("proj_ip", "proj_w", "proj_sv", "proj_k", "proj_era", "proj_whip"), names(out))
  if (length(proj_cols) == 0) {
    out$key <- NULL
    rownames(out) <- NULL
    return(out)
  }

  for (sys in ok_systems) {
    dat <- system_results[[sys]]$data
    idx <- match(out$key, dat$key)
    for (col in proj_cols) {
      out[[paste0(col, "__", sys)]] <- suppressWarnings(as.numeric(dat[[col]][idx]))
    }
  }

  weight_vec <- suppressWarnings(as.numeric(weights[ok_systems]))
  names(weight_vec) <- ok_systems
  weight_mat <- matrix(weight_vec, nrow = nrow(out), ncol = length(ok_systems), byrow = TRUE)

  for (col in proj_cols) {
    mat <- sapply(ok_systems, function(sys) out[[paste0(col, "__", sys)]], simplify = "matrix")
    if (!is.matrix(mat)) {
      mat <- matrix(mat, ncol = 1)
    }
    den <- rowSums((!is.na(mat)) * weight_mat, na.rm = TRUE)
    num <- rowSums(mat * weight_mat, na.rm = TRUE)
    out[[col]] <- ifelse(den > 0, num / den, NA_real_)
  }

  drop_cols <- unlist(lapply(ok_systems, function(sys) paste0(proj_cols, "__", sys)), use.names = FALSE)
  out <- out[, setdiff(names(out), drop_cols), drop = FALSE]
  out <- out[order(is.na(out$adp), out$adp, out$player_name), , drop = FALSE]
  out$key <- NULL
  rownames(out) <- NULL
  out
}

build_run_data_rows <- function(result, inputs) {
  systems_txt <- paste(inputs$systems, collapse = ",")

  adp_draft_type_chr <- coalesce_chr(inputs$adp_draft_type, fallback = "")
  adp_num_teams_chr <- coalesce_chr(inputs$adp_num_teams, fallback = "")

  draft_label <- if (adp_draft_type_chr %in% unname(adp_draft_type_choices)) {
    names(adp_draft_type_choices)[match(adp_draft_type_chr, unname(adp_draft_type_choices))]
  } else {
    if (nzchar(adp_draft_type_chr)) sprintf("Draft Type %s", adp_draft_type_chr) else "All Drafts (Non Auction)"
  }

  adp_from <- coalesce_chr(result$nfbc_adp_from_date, fallback = "")
  adp_to <- coalesce_chr(result$nfbc_adp_to_date, fallback = "")

  if (!nzchar(adp_to)) {
    adp_to <- as.character(Sys.Date())
  }
  if (!nzchar(adp_from)) {
    adp_from <- as.character(as.Date(adp_to) - as.integer(inputs$adp_lookback_days))
  }

  p_base_names <- names(inputs$pitcher_weights)
  p_low_names <- names(inputs$pitcher_low_ip_weights)
  p_high_names <- names(inputs$pitcher_high_ip_weights)
  p_stab_names <- names(inputs$pitcher_stabilization_points)

  data.frame(
    Section = c(
      "Run",
      "Hitter Projection",
      "Pitcher Projection",
      "Hitter Projection",
      "Pitcher Projection",
      rep("Pitcher Projection Weights", length(inputs$pitcher_projection_weights)),
      rep("Hitter Projection Weights", length(inputs$projection_weights)),
      rep("Hitter Stat Weights", length(inputs$category_weights)),
      "Pitcher SP Skillz",
      "Pitcher SP Skillz",
      "Pitcher SP Skillz",
      "Pitcher SP Skillz",
      "Pitcher SP Skillz",
      rep("Pitcher SP Skillz Base Weights", length(inputs$pitcher_weights)),
      rep("Pitcher SP Skillz Low-IP Weights", length(inputs$pitcher_low_ip_weights)),
      rep("Pitcher SP Skillz High-IP Weights", length(inputs$pitcher_high_ip_weights)),
      rep("Pitcher SP Skillz Stabilization Points", length(inputs$pitcher_stabilization_points)),
      "League",
      "League",
      "League",
      "ADP Run",
      "ADP Run",
      "ADP Run",
      "ADP Run"
    ),
    Metric = c(
      "Season",
      "Systems Used",
      "Pitcher Systems Used",
      "Hitter Categories",
      "Pitcher Categories",
      toupper(names(inputs$pitcher_projection_weights)),
      toupper(names(inputs$projection_weights)),
      toupper(names(inputs$category_weights)),
      "Use IP Paradigms",
      "Low-IP Max Start-IP",
      "High-IP Min Start-IP",
      "GS Fallback Threshold",
      "Reliability Method",
      toupper(p_base_names),
      toupper(p_low_names),
      toupper(p_high_names),
      toupper(p_stab_names),
      "Teams",
      "PA Floor",
      "Starter Count",
      "Draft Type",
      "Number of Teams",
      "Date From",
      "Date To"
    ),
    Value = c(
      as.character(inputs$season),
      systems_txt,
      paste(inputs$pitcher_projection_systems, collapse = ","),
      paste(inputs$hitter_categories, collapse = ","),
      paste(inputs$pitcher_categories, collapse = ","),
      as.character(as.numeric(inputs$pitcher_projection_weights)),
      as.character(as.numeric(inputs$projection_weights)),
      as.character(as.numeric(inputs$category_weights)),
      ifelse(isTRUE(inputs$pitcher_use_ip_paradigms), "TRUE", "FALSE"),
      as.character(inputs$pitcher_low_ip_max_start_ip),
      as.character(inputs$pitcher_high_ip_min_start_ip),
      as.character(inputs$pitcher_gs_fallback_threshold),
      as.character(inputs$pitcher_reliability_method),
      as.character(as.numeric(inputs$pitcher_weights)),
      as.character(as.numeric(inputs$pitcher_low_ip_weights)),
      as.character(as.numeric(inputs$pitcher_high_ip_weights)),
      as.character(as.numeric(inputs$pitcher_stabilization_points)),
      as.character(inputs$num_teams),
      as.character(inputs$pa_floor),
      as.character(inputs$starter_count),
      draft_label,
      ifelse(nzchar(adp_num_teams_chr), adp_num_teams_chr, "All Teams"),
      adp_from,
      adp_to
    ),
    stringsAsFactors = FALSE
  )
}

read_cached_output <- function(cfg, season) {
  out_path <- file.path(cfg$paths$processed_dir, sprintf("%s_hitters_z_scored_aggregate_projection_output.csv", season))
  meta_path <- file.path(cfg$paths$processed_dir, sprintf("%s_refresh_metadata.csv", season))

  if (!file.exists(out_path)) {
    return(NULL)
  }

  dat <- tryCatch(utils::read.csv(out_path, stringsAsFactors = FALSE, check.names = FALSE), error = function(e) NULL)
  meta <- tryCatch(utils::read.csv(meta_path, stringsAsFactors = FALSE, check.names = FALSE), error = function(e) NULL)

  list(data = dat, meta = meta)
}

swap_adp_team_columns <- function(dat) {
  if (is.null(dat) || !is.data.frame(dat)) {
    return(dat)
  }
  if (!all(c("adp", "team") %in% names(dat))) {
    return(dat)
  }

  cols <- names(dat)
  adp_idx <- match("adp", cols)
  team_idx <- match("team", cols)
  cols[c(adp_idx, team_idx)] <- cols[c(team_idx, adp_idx)]
  dat[, cols, drop = FALSE]
}

drop_match_flag_columns <- function(dat) {
  if (is.null(dat) || !is.data.frame(dat)) {
    return(dat)
  }
  dat[, setdiff(names(dat), c("adp_match_quality", "name_team_flag")), drop = FALSE]
}

summary_strip_ui <- function(suffix) {
  layout_columns(
    col_widths = c(4, 4, 4),
    card(class = "metric-card", card_header("Last Completed Run"), htmlOutput(paste0("summary_snapshot_", suffix))),
    card(class = "metric-card", card_header("Dataset Counts"), htmlOutput(paste0("summary_counts_", suffix))),
    card(class = "metric-card", card_header("Run Parameters"), htmlOutput(paste0("summary_filters_", suffix)))
  )
}

