server <- function(input, output, session) {
  cfg <- reactiveVal(load_pipeline_config(file.path("config", "pipeline.yml")))

  rv <- reactiveValues(
    output_data = NULL,
    hitter_zscores = NULL,
    pitcher_sp_skillz = NULL,
    pitcher_data = NULL,
    adp_data = NULL,
    run_data = NULL,
    controls_seeded_from_run_data = FALSE,
    team_import_seed_force = FALSE,
    team_import_seed = list(hitters = list(), pitchers = list(), bench = list()),
    team_import_status = "No team import loaded.",
    status = "Ready. Click 'Fetch Data' to load projections and ADP.",
    # Team Importer wizard
    team_wizard_step = 1L,
    # Streamonator
    stream_probables    = NULL,      # parsed probables data frame
    stream_park_factors = NULL,      # loaded park factors
    stream_status       = "Click 'Fetch Probables' to load the probables grid."
  )

  observeEvent(input$toggle_sidebar_btn, {
    bslib::sidebar_toggle("controls_sidebar", session = session)
  })

  session$onFlushed(function() {
    bslib::accordion_panel_close(
      id = "player_comparison_inputs_sections",
      values = c(
        "comparison_hitters_inputs_panel",
        "comparison_pitchers_inputs_panel",
        "comparison_hypothetical_panel"
      ),
      session = session
    )

    cfg_cats <- isolate(cfg())$projection$categories
    if (!is.null(cfg_cats) && length(cfg_cats) > 0) {
      valid_ui_cats <- unname(hitter_category_choices)
      seeded <- intersect(tolower(as.character(cfg_cats)), valid_ui_cats)
      if (length(seeded) > 0) {
        updateCheckboxGroupInput(session, "hitter_categories", selected = seeded)
      }
    }
  }, once = TRUE)

  observeEvent(input$projection_weight_preset, {
    preset <- projection_weight_presets[[as.character(input$projection_weight_preset)]]
    req(!is.null(preset))
    updateNumericInput(session, "w_batx", value = as.numeric(preset[["batx"]]))
    updateNumericInput(session, "w_steamer", value = as.numeric(preset[["steamer"]]))
    updateNumericInput(session, "w_oopsy", value = as.numeric(preset[["oopsy"]]))
    updateNumericInput(session, "w_atc", value = as.numeric(preset[["atc"]]))
  }, ignoreInit = TRUE)

  observeEvent(input$stat_weight_preset, {
    preset_name <- as.character(input$stat_weight_preset)
    preset <- stat_weight_presets[[preset_name]]
    req(!is.null(preset))

    selected <- normalize_selected_hitter_categories(input$hitter_categories)
    if (length(selected) == 0) {
      selected <- default_hitter_categories
    }

    set_weight <- function(metric, input_id) {
      base <- as.numeric(preset[[metric]])
      val <- if (metric %in% selected) base else 0
      updateNumericInput(session, input_id, value = val)
    }

    set_weight("hr", "sw_hr")
    set_weight("sb", "sw_sb")
    set_weight("avg", "sw_avg")
    set_weight("r", "sw_r")
    set_weight("rbi", "sw_rbi")
    set_weight("obp", "sw_obp")
    updateNumericInput(session, "sw_pa", value = as.numeric(preset[["pa"]]))
  }, ignoreInit = TRUE)

  observeEvent(input$hitter_categories, {
    # Keep the numeric stat weights in sync with the active preset when category
    # membership changes (e.g., swapping AVG <-> OBP).
    preset_name <- as.character(input$stat_weight_preset %||% "ck")
    preset <- stat_weight_presets[[preset_name]]
    req(!is.null(preset))

    selected <- normalize_selected_hitter_categories(input$hitter_categories)
    if (length(selected) == 0) {
      selected <- default_hitter_categories
    }

    set_weight <- function(metric, input_id) {
      base <- as.numeric(preset[[metric]])
      val <- if (metric %in% selected) base else 0
      updateNumericInput(session, input_id, value = val)
    }

    set_weight("hr", "sw_hr")
    set_weight("sb", "sw_sb")
    set_weight("avg", "sw_avg")
    set_weight("r", "sw_r")
    set_weight("rbi", "sw_rbi")
    set_weight("obp", "sw_obp")
    updateNumericInput(session, "sw_pa", value = as.numeric(preset[["pa"]]))
  }, ignoreInit = TRUE)

  observeEvent(input$pitcher_projection_weight_preset, {
    updateNumericInput(session, "pw_steamer", value = 1)
    updateNumericInput(session, "pw_oopsy", value = 1)
    updateNumericInput(session, "pw_atc", value = 1)
  }, ignoreInit = TRUE)

  observeEvent(input$team_roster_preset, {
    preset_name <- as.character(input$team_roster_preset %||% "")
    if (!nzchar(preset_name) || identical(preset_name, "Custom")) return()
    preset <- team_roster_presets[[preset_name]]
    req(!is.null(preset))
    updateNumericInput(session, "team_c", value = as_int_safe(preset$team_c, 0L))
    updateNumericInput(session, "team_1b", value = as_int_safe(preset$team_1b, 0L))
    updateNumericInput(session, "team_2b", value = as_int_safe(preset$team_2b, 0L))
    updateNumericInput(session, "team_ss", value = as_int_safe(preset$team_ss, 0L))
    updateNumericInput(session, "team_3b", value = as_int_safe(preset$team_3b, 0L))
    updateNumericInput(session, "team_of", value = as_int_safe(preset$team_of, 0L))
    updateNumericInput(session, "team_mi", value = as_int_safe(preset$team_mi, 0L))
    updateNumericInput(session, "team_ci", value = as_int_safe(preset$team_ci, 0L))
    updateNumericInput(session, "team_if", value = as_int_safe(preset$team_if, 0L))
    updateNumericInput(session, "team_ut", value = as_int_safe(preset$team_ut, 0L))
    updateNumericInput(session, "team_sp", value = as_int_safe(preset$team_sp, 0L))
    updateNumericInput(session, "team_rp", value = as_int_safe(preset$team_rp, 0L))
    updateNumericInput(session, "team_p", value = as_int_safe(preset$team_p, 0L))
    updateNumericInput(session, "team_bench", value = as_int_safe(preset$team_bench, 0L))
    if (identical(preset_name, "NFBC")) {
      updateNumericInput(session, "team_league_teams", value = 15)
    } else if (identical(preset_name, "Ottoneu")) {
      updateNumericInput(session, "team_league_teams", value = 12)
    }
    league_teams <- as_int_safe(input$team_league_teams, 12L)
    draft_pos <- as_int_safe(input$team_draft_position, 1L)
    updateNumericInput(session, "team_draft_position", value = max(1L, min(draft_pos, league_teams)))
  }, ignoreInit = FALSE)

  observe({
    league_teams <- as_int_safe(input$team_league_teams, 12L)
    draft_pos <- as_int_safe(input$team_draft_position, 1L)
    clamped_pos <- max(1L, min(draft_pos, league_teams))
    if (!identical(clamped_pos, draft_pos)) {
      updateNumericInput(session, "team_draft_position", value = clamped_pos)
    }
  })

  observe({
    league_teams <- as_int_safe(input$team_league_teams, 12L)
    draft_pos <- as_int_safe(input$team_draft_position, 1L)
    h_slots <- hitter_slots()
    p_slots <- pitcher_slots()
    b_slots <- bench_slots()

    update_auto_pick <- function(prefix, n_slots) {
      if (n_slots <= 0) return(invisible(NULL))
      for (i in seq_len(n_slots)) {
        rid <- paste0(prefix, "_round_", i)
        oid <- paste0(prefix, "_overall_", i)
        round_value <- as_num_safe(input[[rid]], NA_real_)
        overall_pick <- compute_snake_overall_pick(round_value, league_teams, draft_pos)
        updateNumericInput(session, oid, value = if (is.na(overall_pick)) NA else overall_pick)
      }
    }

    update_auto_pick("team_h", length(h_slots))
    update_auto_pick("team_p", length(p_slots))
    update_auto_pick("team_b", length(b_slots))
  })

  observeEvent(input$load_cached, {
    cached <- read_cached_output(cfg(), season = input$season)
    if (is.null(cached) || is.null(cached$data)) {
      rv$status <- sprintf("No cached output found for season %s.", input$season)
      return()
    }

    rv$output_data <- drop_match_flag_columns(swap_adp_team_columns(cached$data))
    rv$hitter_zscores <- read_cached_hitter_zscores(cfg(), season = input$season)
    rv$pitcher_sp_skillz <- add_pitcher_role_sp_skillz(read_cached_pitcher_sp_skillz(cfg()))
    rv$pitcher_data <- add_pitcher_role_integrated(read_cached_pitcher_output(cfg(), season = input$season))
    rv$adp_data <- read_cached_adp_output(cfg(), season = input$season)
    rv$controls_seeded_from_run_data <- FALSE
    rv$run_data <- read_cached_run_data(cfg(), season = input$season)

    rv$status <- sprintf("Loaded cached output for season %s (%s rows).", input$season, nrow(rv$output_data))
  })

  observeEvent(input$run_model, {
    if (length(input$systems) == 0) {
      showNotification("Select at least one projection system.", type = "error")
      rv$status <- "No systems selected."
      return()
    }
    if (length(normalize_selected_hitter_categories(input$hitter_categories)) == 0) {
      showNotification("Select at least one hitter category.", type = "error")
      rv$status <- "No hitter categories selected."
      return()
    }
    if (length(input$pitcher_systems) == 0) {
      showNotification("Select at least one pitcher projection system.", type = "error")
      rv$status <- "No pitcher systems selected."
      return()
    }

    projection_weights <- c(
      batx = as.numeric(input$w_batx),
      steamer = as.numeric(input$w_steamer),
      oopsy = as.numeric(input$w_oopsy),
      atc = as.numeric(input$w_atc)
    )

    pitcher_projection_weights <- c(
      steamer = as.numeric(input$pw_steamer),
      oopsy = as.numeric(input$pw_oopsy),
      atc = as.numeric(input$pw_atc)
    )
    selected_pitcher_weights <- pitcher_projection_weights[input$pitcher_systems]
    if (any(is.na(selected_pitcher_weights)) || any(selected_pitcher_weights < 0) || sum(selected_pitcher_weights) <= 0) {
      showNotification("Pitcher projection weights must be non-negative and sum to more than 0.", type = "error")
      rv$status <- "Invalid pitcher projection weights."
      return()
    }

    selected_hitter_categories <- normalize_selected_hitter_categories(input$hitter_categories)

    category_weights <- c(
      pa = as.numeric(input$sw_pa),
      hr = as.numeric(input$sw_hr),
      sb = as.numeric(input$sw_sb),
      avg = as.numeric(input$sw_avg),
      r = as.numeric(input$sw_r),
      rbi = as.numeric(input$sw_rbi),
      obp = as.numeric(input$sw_obp)
    )

    starter_count <- as.integer(as.numeric(input$num_teams) * sum(cfg()$projection$league$hitter_slots, na.rm = TRUE))
    adp_draft_type_val <- suppressWarnings(as.integer(input$adp_draft_type))
    adp_num_teams_val <- suppressWarnings(as.integer(input$adp_num_teams))

    configured_local_adp <- cfg()$adp$local_tsv
    adp_local_fallback <- ""
    if (isTRUE(input$use_local_adp) && nzchar(configured_local_adp) && file.exists(configured_local_adp)) {
      adp_local_fallback <- configured_local_adp
    }

      inputs_used <- list(
        season = as.integer(input$season),
        systems = input$systems,
        pitcher_projection_systems = as.character(input$pitcher_systems),
        pitcher_projection_weights = selected_pitcher_weights,
        projection_weights = projection_weights[input$systems],
        hitter_categories = selected_hitter_categories,
        pitcher_categories = as.character(input$pitcher_categories %||% character(0)),
        category_weights = category_weights,
        pitcher_use_ip_paradigms = isTRUE(cfg()$pitcher$sp_skillz$use_ip_paradigms),
      pitcher_low_ip_max_start_ip = as.numeric(cfg()$pitcher$sp_skillz$low_ip_max_start_ip),
      pitcher_high_ip_min_start_ip = as.numeric(cfg()$pitcher$sp_skillz$high_ip_min_start_ip),
      pitcher_gs_fallback_threshold = as.numeric(cfg()$pitcher$sp_skillz$gs_fallback_threshold),
      pitcher_reliability_method = as.character(cfg()$pitcher$sp_skillz$reliability_method),
      pitcher_weights = cfg()$pitcher$sp_skillz$weights,
      pitcher_low_ip_weights = cfg()$pitcher$sp_skillz$low_ip_weights,
      pitcher_high_ip_weights = cfg()$pitcher$sp_skillz$high_ip_weights,
      pitcher_stabilization_points = cfg()$pitcher$sp_skillz$stabilization_points,
      pa_floor = as.numeric(input$pa_floor),
      num_teams = as.integer(input$num_teams),
      starter_count = starter_count,
      total_budget = as.numeric(input$total_budget),
      hitter_budget_share = as.numeric(input$hitter_budget_share),
      min_bid = as.numeric(input$min_bid),
      adp_draft_type = adp_draft_type_val,
      adp_num_teams = adp_num_teams_val,
      adp_lookback_days = as.integer(input$adp_lookback_days)
    )

    rv$status <- "Running model..."
    dir.create(cfg()$paths$raw_dir, recursive = TRUE, showWarnings = FALSE)
    dir.create(cfg()$paths$processed_dir, recursive = TRUE, showWarnings = FALSE)
    adp_raw_path <- file.path(cfg()$paths$raw_dir, sprintf("%s_nfbc_adp.tsv", as.integer(input$season)))

    withProgress(message = "Refreshing projections", value = 0.1, {
      run_hitter_pipeline <- function(local_adp_path = "") {
        fetch_all_systems(
          systems = input$systems,
          season = as.integer(input$season),
          weights = projection_weights,
          pa_floor = as.numeric(input$pa_floor),
          category_weights = category_weights,
          category_selection = selected_hitter_categories,
          starter_count = starter_count,
          starter_rank_metric = cfg()$projection$starter_rank_metric,
          num_teams = as.integer(input$num_teams),
          total_budget = as.numeric(input$total_budget),
          hitter_budget_share = as.numeric(input$hitter_budget_share),
          min_bid = as.numeric(input$min_bid),
          adp_local_tsv_path = local_adp_path,
          adp_fill_missing_with_max = isTRUE(cfg()$adp$fill_missing_with_max),
          adp_lookback_days = as.integer(input$adp_lookback_days),
          adp_draft_type = adp_draft_type_val,
          adp_num_teams = adp_num_teams_val,
          adp_raw_output_path = adp_raw_path,
          player_match_overrides_path = cfg()$paths$match_overrides_csv,
          quality = cfg()$quality
        )
      }

      result <- tryCatch(run_hitter_pipeline(local_adp_path = ""), error = function(e) e)

      if (!inherits(result, "error") &&
          identical(coalesce_chr(result$nfbc_adp_source, fallback = ""), "unavailable") &&
          nzchar(adp_local_fallback)) {
        showNotification("Live ADP pull failed; retrying with cached local ADP.tsv.", type = "warning", duration = 6)
        result_retry <- tryCatch(run_hitter_pipeline(local_adp_path = adp_local_fallback), error = function(e) e)
        if (!inherits(result_retry, "error")) {
          result <- result_retry
        }
      }

      incProgress(0.9)

      if (inherits(result, "error")) {
        rv$status <- sprintf("Run failed: %s", conditionMessage(result))
        showNotification(conditionMessage(result), type = "error", duration = NULL)
        return()
      }

      rv$output_data <- drop_match_flag_columns(swap_adp_team_columns(result$z_scored_aggregate_projection_output))
      rv$hitter_zscores <- if (is.data.frame(result$z_scores)) result$z_scores else read_cached_hitter_zscores(cfg(), season = input$season)
      # ADP board should use full-player ADP (hitters + pitchers), not hitter-only merge input.
      rv$adp_data <- read_cached_adp_output(cfg(), season = input$season)
      if (is.null(rv$adp_data)) {
        # Last-resort fallback if expected ADP files are unavailable.
        rv$adp_data <- prepare_adp_table(result$nfbc_adp)
      }
      rv$controls_seeded_from_run_data <- TRUE
      rv$run_data <- build_run_data_rows(result, inputs_used)
      rv$status <- sprintf(
        "Run complete: %s hitters ranked | ADP source: %s",
        nrow(rv$output_data),
        coalesce_chr(result$nfbc_adp_source, fallback = "unknown")
      )
      if (identical(result$nfbc_adp_source, "local_fallback") || identical(result$nfbc_adp_source, "local_file")) {
        fallback_msg <- coalesce_chr(
          result$nfbc_adp_warning_message,
          fallback = "ADP live pull failed; using cached local ADP.tsv for this run."
        )
        showNotification(fallback_msg, type = "warning", duration = NULL)
      }

      out_path <- file.path(cfg()$paths$processed_dir, sprintf("%s_hitters_z_scored_aggregate_projection_output.csv", as.integer(input$season)))
      dir.create(dirname(out_path), recursive = TRUE, showWarnings = FALSE)
      utils::write.csv(rv$output_data, out_path, row.names = FALSE, na = "")
      run_data_snapshot_path <- file.path(cfg()$paths$processed_dir, sprintf("%s_run_data_snapshot.csv", as.integer(input$season)))
      utils::write.csv(rv$run_data, run_data_snapshot_path, row.names = FALSE, na = "")

      pitcher_adp_tsv <- resolve_existing_file(c(
        result$nfbc_adp_source_path,
        adp_raw_path,
        adp_local_fallback,
        configured_local_adp
      ))

      pitcher_ok <- FALSE
      pitcher_logs <- character(0)
      if (!nzchar(pitcher_adp_tsv)) {
        rv$pitcher_sp_skillz <- NULL
        rv$pitcher_data <- NULL
        pitcher_logs <- c(pitcher_logs, "No ADP TSV available for pitcher integration.")
      } else {
        pitcher_results <- list()
        for (sys in input$pitcher_systems) {
          res <- run_pitcher_integration_system(
            cfg_path = file.path("config", "pipeline.yml"),
            season = as.integer(input$season),
            adp_tsv_path = pitcher_adp_tsv,
            system_name = sys,
            raw_dir = cfg()$paths$raw_dir
          )
          if (isTRUE(res$ok)) {
            pitcher_results[[sys]] <- res
          } else {
            msg <- coalesce_chr(res$log, fallback = "unknown failure")
            pitcher_logs <- c(pitcher_logs, sprintf("%s: %s", toupper(sys), msg))
          }
        }

        if (length(pitcher_results) > 0) {
          weighted_pitchers <- blend_pitcher_integration_outputs(
            system_results = pitcher_results,
            weights = selected_pitcher_weights
          )
          rv$pitcher_data <- add_pitcher_role_integrated(weighted_pitchers)
          rv$pitcher_sp_skillz <- add_pitcher_role_sp_skillz(read_cached_pitcher_sp_skillz(cfg()))
          pitcher_ok <- !is.null(rv$pitcher_data) && is.data.frame(rv$pitcher_data) && nrow(rv$pitcher_data) > 0
          if (length(pitcher_logs) > 0) {
            showNotification(
              sprintf("Some pitcher systems failed and were skipped: %s", paste(pitcher_logs, collapse = " | ")),
              type = "warning",
              duration = 8
            )
          }
        } else {
          rv$pitcher_sp_skillz <- NULL
          rv$pitcher_data <- NULL
        }
      }

      if (!pitcher_ok) {
        pitcher_log <- paste(pitcher_logs, collapse = " | ")
        if (nzchar(pitcher_log)) {
          rv$status <- sprintf(
            "Pitcher refresh failed; hitter output updated. Details: %s",
            substr(gsub("[\r\n]+", " ", pitcher_log), 1, 260)
          )
        }
        showNotification("Pitcher table refresh failed. Hitter output was still updated.", type = "warning", duration = 8)
      }

      pitcher_rows <- if (is.null(rv$pitcher_data)) 0L else nrow(rv$pitcher_data)
      adp_rows <- if (is.null(rv$adp_data)) 0L else nrow(rv$adp_data)
      rv$status <- sprintf(
        "Run complete: %s hitters ranked | %s pitchers integrated | %s ADP rows | ADP source: %s",
        nrow(rv$output_data),
        pitcher_rows,
        adp_rows,
        coalesce_chr(result$nfbc_adp_source, fallback = "unknown")
      )

      })
  })

  dt_opts <- list(
    pageLength = 100,
    lengthMenu = list(
      c(50, 100, 200, -1),
      c("50", "100", "200", "All")
    ),
    scrollX = TRUE,
    orderCellsTop = TRUE,
    autoWidth = TRUE,
    deferRender = TRUE
  )
  dt_callback <- JS("
    function updateOrdinalRank(dt) {
      if (!dt || !dt.column || dt.columns().count() === 0) return;
      var info = dt.page.info();
      var total = info.recordsDisplay || dt.rows({ search: 'applied' }).count();
      var order = dt.order();
      var sortCol = (order && order.length) ? order[0][0] : 0;
      var dir = (order && order.length) ? order[0][1] : 'asc';
      var settings = dt.settings()[0] || {};
      var prefMap = (settings.oInit && settings.oInit.rankPreferredDir) ? settings.oInit.rankPreferredDir : {};
      var prefDir = (prefMap && Object.prototype.hasOwnProperty.call(prefMap, String(sortCol))) ? prefMap[String(sortCol)] : 'asc';
      var forward = (dir === prefDir);

      dt.column(0, { page: 'current' }).nodes().each(function(cell, i) {
        var pos = info.start + i;
        var rank = forward ? (pos + 1) : (total - pos);
        cell.innerHTML = rank;
      });
    }
    function relayoutFixed(dt) {
      if (!dt) return;
      try { dt.columns.adjust(); } catch (e) {}
      try {
        if (dt.fixedColumns && dt.fixedColumns()) {
          dt.fixedColumns().relayout();
        }
      } catch (e) {}
    }

    if (window.enableDtRangeFilter) { window.enableDtRangeFilter(table); }
    updateOrdinalRank(table);
    relayoutFixed(table);
    setTimeout(function(){ relayoutFixed(table); }, 50);
    setTimeout(function(){ relayoutFixed(table); }, 220);

    table.on('order.dt search.dt draw.dt column-visibility.dt', function() {
      updateOrdinalRank(table);
      relayoutFixed(table);
    });

    $(window).off('resize.codexdt').on('resize.codexdt', function() {
      relayoutFixed(table);
    });
    $(document).off('shown.bs.tab.codexdt').on('shown.bs.tab.codexdt', function() {
      relayoutFixed(table);
    });
  ")

  normalize_col_key <- function(x) {
    gsub("[^a-z0-9]+", "", tolower(as.character(x)))
  }

  add_rank_column <- function(dat) {
    if (is.null(dat) || !is.data.frame(dat)) return(dat)
    n <- nrow(dat)
    data.frame(rank = seq_len(n), dat, check.names = FALSE, stringsAsFactors = FALSE)
  }

  reorder_front_columns <- function(dat, front_cols) {
    if (is.null(dat) || !is.data.frame(dat)) return(dat)
    front <- intersect(front_cols, names(dat))
    dat[, c(front, setdiff(names(dat), front)), drop = FALSE]
  }

  smart_order_column_defs <- function(col_names) {
    keys <- normalize_col_key(col_names)
    desc_first_keys <- c(
      "pa", "hr", "sb", "r", "rbi", "h", "avg",
      "paz", "hrz", "sbz", "rz", "rbiz", "avgz",
      "ztotalraw", "ztotalweights",
      "dollarsraw", "dollarsweights", "dollarsadp",
      "projip", "projw", "projsv", "projk", "ip", "gs",
      "spskillzscore", "spskillzscorestabilized",
      "stuff", "stuffplus", "pitching", "pitchingplus",
      "csw", "cswpct", "kbb", "kbbpct"
    )
    asc_first_keys <- c(
      "rank", "team", "name", "playername", "position", "positions",
      "adp", "adprk", "adprank", "nfbcrank", "adpminpick", "adpmaxpick",
      "projera", "projwhip", "siera", "xfip",
      "spskillzrank", "spskillzrankstabilized",
      "sp25rank", "sp26rank", "eno", "ck", "ds"
    )

    desc_targets <- which(keys %in% desc_first_keys) - 1L
    asc_targets <- which(keys %in% asc_first_keys) - 1L

    defs <- list(
      list(targets = 0L, orderSequence = c("asc", "desc"), className = "dt-body-right", searchable = FALSE, width = "58px")
    )
    if (length(desc_targets) > 0) {
      defs <- c(defs, list(list(targets = as.integer(desc_targets), orderSequence = c("desc", "asc"))))
    }
    if (length(asc_targets) > 0) {
      defs <- c(defs, list(list(targets = as.integer(asc_targets), orderSequence = c("asc", "desc"))))
    }
    preferred <- rep("asc", length(col_names))
    if (length(desc_targets) > 0) {
      preferred[desc_targets + 1L] <- "desc"
    }
    preferred[1] <- "asc"

    list(column_defs = defs, preferred_dirs = preferred)
  }

  build_table_options <- function(dat, base_opts = dt_opts, extra_defs = list()) {
    freeze_left_columns <- function(col_names) {
      keys <- normalize_col_key(col_names)
      idx_rank <- which(keys == "rank")
      idx_name <- which(keys %in% c("playername", "name"))
      idx_pos <- which(keys %in% c("position", "positions"))
      idx_adp <- which(keys == "adp")
      idx_team <- which(keys == "team")
      anchors <- c(idx_rank, idx_name, idx_team, idx_pos, idx_adp)
      anchors <- anchors[!is.na(anchors) & anchors > 0]
      if (length(anchors) == 0) return(1L)
      as.integer(max(anchors))
    }

    opts <- base_opts
    order_meta <- smart_order_column_defs(names(dat))
    existing_defs <- opts$columnDefs
    opts$columnDefs <- c(
      order_meta$column_defs,
      extra_defs,
      if (is.null(existing_defs)) list() else existing_defs
    )
    opts$order <- list(list(0L, "asc"))
    opts$rankPreferredDir <- as.list(stats::setNames(
      as.character(order_meta$preferred_dirs),
      as.character(seq_along(order_meta$preferred_dirs) - 1L)
    ))
    opts$fixedColumns <- list(leftColumns = freeze_left_columns(names(dat)))
    opts$fixedHeader <- TRUE
    opts
  }

  filtered_adp <- reactive({
    dat <- rv$adp_data
    req(dat)
    selected <- input$adp_pos_filter
    if (is.null(selected) || length(selected) == 0) {
      return(dat[0, , drop = FALSE])
    }
    if (!"positions" %in% names(dat)) {
      return(dat)
    }
    keep <- row_has_any_position(dat$positions, toupper(selected))
    dat[keep, , drop = FALSE]
  })

  adp_lookup <- reactive({
    dat <- rv$adp_data
    if (is.null(dat) || !is.data.frame(dat) || nrow(dat) == 0) {
      return(data.frame(
        key = character(0),
        player_name = character(0),
        adp = numeric(0),
        positions = character(0),
        team = character(0),
        stringsAsFactors = FALSE
      ))
    }
    player_name <- as.character(col_or_na(dat, c("player_name", "Player", "name")))
    team <- as.character(col_or_na(dat, c("team", "Team")))
    positions <- as.character(col_or_na(dat, c("positions", "position", "Position(s)", "Position")))
    adp <- suppressWarnings(as.numeric(col_or_na(dat, c("adp", "ADP"))))
    out <- data.frame(
      key = make_player_key(player_name, team),
      player_name = player_name,
      adp = adp,
      positions = positions,
      team = team,
      stringsAsFactors = FALSE
    )
    out <- out[!duplicated(out$key), , drop = FALSE]
    out <- out[order(out$adp, out$player_name, na.last = TRUE), , drop = FALSE]
    out
  })

  adp_suggestion_pool <- reactive({
    lu <- adp_lookup()
    if (nrow(lu) == 0) {
      return(data.frame(key = character(0), label = character(0), positions = character(0), stringsAsFactors = FALSE))
    }
    label <- make_dropdown_labels(lu$player_name, lu$team)
    data.frame(
      key = lu$key,
      label = label,
      positions = lu$positions,
      stringsAsFactors = FALSE
    )
  })

  hitter_source <- reactive({
    dat <- valued_hitter_output()
    if (is.null(dat) || !is.data.frame(dat) || nrow(dat) == 0) {
      return(data.frame(
        key = character(0),
        player_name = character(0),
        team = character(0),
        position = character(0),
        adp = numeric(0),
        ab = numeric(0),
        h = numeric(0),
        bb = numeric(0),
        pa = numeric(0),
        hr = numeric(0),
        sb = numeric(0),
        r = numeric(0),
        rbi = numeric(0),
        avg = numeric(0),
        obp = numeric(0),
        hr_z = numeric(0),
        sb_z = numeric(0),
        r_z = numeric(0),
        rbi_z = numeric(0),
        avg_z = numeric(0),
        obp_z = numeric(0),
        z_total_weights = numeric(0),
        dollars_weights = numeric(0),
        stringsAsFactors = FALSE
      ))
    }

    out <- data.frame(
      player_name = as.character(col_or_na(dat, c("player_name", "name", "Name"))),
      team = as.character(col_or_na(dat, c("team", "Team"))),
      position = as.character(col_or_na(dat, c("position", "positions", "Position"))),
      adp = suppressWarnings(as.numeric(col_or_na(dat, c("adp", "ADP")))),
      ab = suppressWarnings(as.numeric(col_or_na(dat, c("ab", "AB")))),
      h = suppressWarnings(as.numeric(col_or_na(dat, c("h", "H")))),
      bb = suppressWarnings(as.numeric(col_or_na(dat, c("bb", "BB")))),
      pa = suppressWarnings(as.numeric(col_or_na(dat, c("pa", "PA")))),
      hr = suppressWarnings(as.numeric(col_or_na(dat, c("hr", "HR")))),
      sb = suppressWarnings(as.numeric(col_or_na(dat, c("sb", "SB")))),
      r = suppressWarnings(as.numeric(col_or_na(dat, c("r", "R")))),
      rbi = suppressWarnings(as.numeric(col_or_na(dat, c("rbi", "RBI")))),
      avg = suppressWarnings(as.numeric(col_or_na(dat, c("avg", "AVG")))),
      obp = suppressWarnings(as.numeric(col_or_na(dat, c("obp", "OBP")))),
      hr_z = suppressWarnings(as.numeric(col_or_na(dat, c("hr_z", "HR_z")))),
      sb_z = suppressWarnings(as.numeric(col_or_na(dat, c("sb_z", "SB_z")))),
      r_z = suppressWarnings(as.numeric(col_or_na(dat, c("r_z", "R_z")))),
      rbi_z = suppressWarnings(as.numeric(col_or_na(dat, c("rbi_z", "RBI_z")))),
      avg_z = suppressWarnings(as.numeric(col_or_na(dat, c("avg_z", "AVG_z")))),
      obp_z = suppressWarnings(as.numeric(col_or_na(dat, c("obp_z", "OBP_z")))),
      z_total_weights = suppressWarnings(as.numeric(col_or_na(dat, c("z_total_weights", "z_total_custom", "Z_total_weights")))),
      dollars_weights = suppressWarnings(as.numeric(col_or_na(dat, c("dollars_weights", "Dollars.Weights")))),
      stringsAsFactors = FALSE
    )
    out$key <- make_player_key(out$player_name, out$team)
    out <- out[!duplicated(out$key), , drop = FALSE]

    # Fill AB/H from ATC standard output when the blended hitter output omits them.
    atc_ref <- read_cached_atc_hitter_reference(cfg(), season = as.integer(input$season))
    if (!is.null(atc_ref) && is.list(atc_ref) && !is.null(atc_ref$by_key)) {
      by_key <- atc_ref$by_key
      by_name <- atc_ref$by_name

      key_match <- match(out$key, by_key$key)
      fill_ab_key <- is.na(out$ab) & !is.na(key_match)
      fill_h_key <- is.na(out$h) & !is.na(key_match)
      out$ab[fill_ab_key] <- by_key$ab[key_match[fill_ab_key]]
      out$h[fill_h_key] <- by_key$h[key_match[fill_h_key]]

      name_key <- normalize_join_name(out$player_name)
      name_match <- match(name_key, by_name$name_key)
      fill_ab_name <- is.na(out$ab) & !is.na(name_match)
      fill_h_name <- is.na(out$h) & !is.na(name_match)
      out$ab[fill_ab_name] <- by_name$ab[name_match[fill_ab_name]]
      out$h[fill_h_name] <- by_name$h[name_match[fill_h_name]]
    }

    # Fall back to H = AVG * AB when H is missing and AB/AVG are available.
    fill_h_from_avg <- is.na(out$h) & !is.na(out$ab) & !is.na(out$avg)
    out$h[fill_h_from_avg] <- out$ab[fill_h_from_avg] * out$avg[fill_h_from_avg]

    fill_obp <- is.na(out$obp) & !is.na(out$h) & !is.na(out$bb) & !is.na(out$pa) & out$pa > 0
    out$obp[fill_obp] <- (out$h[fill_obp] + out$bb[fill_obp]) / out$pa[fill_obp]

    adp_lu <- adp_lookup()
    if (nrow(adp_lu) > 0) {
      m <- match(out$key, adp_lu$key)
      fill_idx <- is.na(out$adp) & !is.na(m)
      out$adp[fill_idx] <- adp_lu$adp[m[fill_idx]]
    }

    out$adp_min_pick <- NA_real_
    out$adp_max_pick <- NA_real_
    adp_raw <- rv$adp_data
    if (!is.null(adp_raw) && is.data.frame(adp_raw) && nrow(adp_raw) > 0 &&
        "adp_min_pick" %in% names(adp_raw) && "adp_max_pick" %in% names(adp_raw)) {
      raw_key <- make_player_key(
        as.character(col_or_na(adp_raw, c("player_name", "Player", "name"))),
        as.character(col_or_na(adp_raw, c("team", "Team")))
      )
      m2 <- match(out$key, raw_key)
      valid <- !is.na(m2)
      out$adp_min_pick[valid] <- adp_raw$adp_min_pick[m2[valid]]
      out$adp_max_pick[valid] <- adp_raw$adp_max_pick[m2[valid]]
    }

    ord <- order(-out$dollars_weights, out$adp, out$player_name, na.last = TRUE)
    out <- out[ord, , drop = FALSE]
    rownames(out) <- NULL
    out
  })

  pitcher_source <- reactive({
    dat <- rv$pitcher_data
    if (is.null(dat) || !is.data.frame(dat) || nrow(dat) == 0) {
      return(data.frame(
        key = character(0),
        player_name = character(0),
        team = character(0),
        adp = numeric(0),
        proj_ip = numeric(0),
        proj_w = numeric(0),
        proj_k = numeric(0),
        proj_sv = numeric(0),
        proj_era = numeric(0),
        proj_whip = numeric(0),
        adp_min_pick = numeric(0),
        adp_max_pick = numeric(0),
        stringsAsFactors = FALSE
      ))
    }

    out <- data.frame(
      player_name = as.character(col_or_na(dat, c("player_name", "name", "Name"))),
      team = as.character(col_or_na(dat, c("team", "Team"))),
      adp = suppressWarnings(as.numeric(col_or_na(dat, c("adp", "ADP")))),
      proj_ip = suppressWarnings(as.numeric(col_or_na(dat, c("proj_ip", "Proj IP")))),
      proj_w = suppressWarnings(as.numeric(col_or_na(dat, c("proj_w", "Proj W")))),
      proj_k = suppressWarnings(as.numeric(col_or_na(dat, c("proj_k", "Proj K")))),
      proj_sv = suppressWarnings(as.numeric(col_or_na(dat, c("proj_sv", "Proj SV")))),
      proj_era = suppressWarnings(as.numeric(col_or_na(dat, c("proj_era", "Proj ERA")))),
      proj_whip = suppressWarnings(as.numeric(col_or_na(dat, c("proj_whip", "Proj WHIP")))),
      stringsAsFactors = FALSE
    )
    out$key <- make_player_key(out$player_name, out$team)
    out <- out[!duplicated(out$key), , drop = FALSE]

    adp_lu <- adp_lookup()
    if (nrow(adp_lu) > 0) {
      m <- match(out$key, adp_lu$key)
      fill_idx <- is.na(out$adp) & !is.na(m)
      out$adp[fill_idx] <- adp_lu$adp[m[fill_idx]]
    }

    # Supplement with RP projections for relievers in the ADP pool but not in the SP table
    adp_raw <- rv$adp_data
    adp_keys <- if (!is.null(adp_raw) && is.data.frame(adp_raw) && nrow(adp_raw) > 0) {
      make_player_key(
        as.character(col_or_na(adp_raw, c("player_name", "Player", "name"))),
        as.character(col_or_na(adp_raw, c("team", "Team")))
      )
    } else character(0)

    rp_supp <- tryCatch(
      read_pitcher_rp_supplement(cfg(), as.integer(input$season %||% 2026L), adp_keys),
      error = function(e) NULL
    )
    if (!is.null(rp_supp) && is.data.frame(rp_supp) && nrow(rp_supp) > 0) {
      new_rps <- rp_supp[!rp_supp$key %in% out$key, , drop = FALSE]
      if (nrow(new_rps) > 0) {
        # Align columns — add any missing cols to new_rps
        for (col_name in setdiff(names(out), names(new_rps))) new_rps[[col_name]] <- NA
        new_rps <- new_rps[, names(out), drop = FALSE]
        out <- rbind(out, new_rps)
      }
    }

    out$adp_min_pick <- NA_real_
    out$adp_max_pick <- NA_real_
    if (!is.null(adp_raw) && is.data.frame(adp_raw) && nrow(adp_raw) > 0 &&
        "adp_min_pick" %in% names(adp_raw) && "adp_max_pick" %in% names(adp_raw)) {
      raw_key <- make_player_key(
        as.character(col_or_na(adp_raw, c("player_name", "Player", "name"))),
        as.character(col_or_na(adp_raw, c("team", "Team")))
      )
      m2 <- match(out$key, raw_key)
      valid <- !is.na(m2)
      out$adp_min_pick[valid] <- adp_raw$adp_min_pick[m2[valid]]
      out$adp_max_pick[valid] <- adp_raw$adp_max_pick[m2[valid]]
    }

    ord <- order(out$adp, -out$proj_ip, out$player_name, na.last = TRUE)
    out <- out[ord, , drop = FALSE]
    rownames(out) <- NULL
    out
  })

  bench_source <- reactive({
