        key = pit$key, stringsAsFactors = FALSE
      )
    )
    out <- out[!duplicated(out$key), , drop = FALSE]
    ord <- order(out$adp, out$player_name, na.last = TRUE)
    out[ord, , drop = FALSE]
  })

