  comparison_hypothetical_data <- reactive({
    src <- hitter_source()
    if (is.null(src) || !is.data.frame(src) || nrow(src) == 0) {
      return(list(data = data.frame(), message = "No hitter data loaded yet."))
    }

    selected_key <- trimws(as.character(input$comparison_hyp_player %||% ""))
    if (!nzchar(selected_key)) {
      return(list(data = data.frame(), message = "Select a hitter to generate hypothetical PA scenarios."))
    }
    idx <- match(selected_key, src$key)
    if (is.na(idx)) {
      return(list(data = data.frame(), message = "Selected hitter was not found in the current hitter dataset."))
    }

    pa_targets <- vapply(seq_len(5), function(i) as_num_safe(input[[paste0("hyp_pa_", i)]], NA_real_), numeric(1))
    if (any(!is.finite(pa_targets)) || any(pa_targets <= 0)) {
      return(list(data = data.frame(), message = "All PA thresholds must be positive numbers."))
    }

    weights_raw <- vapply(seq_len(5), function(i) as_num_safe(input[[paste0("hyp_w_", i)]], 0), numeric(1))
    weights_raw[!is.finite(weights_raw) | weights_raw < 0] <- 0
    if (sum(weights_raw) <= 0) {
      return(list(data = data.frame(), message = "At least one threshold weight must be greater than 0."))
    }
    weights <- weights_raw / sum(weights_raw)

    p <- src[idx, , drop = FALSE]
    base_pa <- as_num_safe(p$pa, NA_real_)
    base_ab <- as_num_safe(p$ab, NA_real_)
    base_h <- as_num_safe(p$h, NA_real_)
    base_bb <- as_num_safe(p$bb, NA_real_)
    base_hr <- as_num_safe(p$hr, 0)
    base_sb <- as_num_safe(p$sb, 0)
    base_r <- as_num_safe(p$r, 0)
    base_rbi <- as_num_safe(p$rbi, 0)
    base_avg <- as_num_safe(p$avg, NA_real_)
    base_obp <- as_num_safe(p$obp, NA_real_)
    base_z <- as_num_safe(p$z_total_weights, NA_real_)
    base_dollars <- as_num_safe(p$dollars_weights, NA_real_)

    if (!is.finite(base_pa) || base_pa <= 0) {
      return(list(data = data.frame(), message = "This hitter has no valid projected PA to scale from."))
    }

    ab_pa_ratio <- suppressWarnings(as.numeric(src$ab) / as.numeric(src$pa))
    ab_pa_ratio <- ab_pa_ratio[is.finite(ab_pa_ratio) & ab_pa_ratio > 0]
    fallback_ab_pa <- if (length(ab_pa_ratio) > 0) stats::median(ab_pa_ratio, na.rm = TRUE) else NA_real_
    if (!is.finite(base_ab) || base_ab <= 0) {
      base_ab <- if (is.finite(fallback_ab_pa)) base_pa * fallback_ab_pa else NA_real_
    }
    if (!is.finite(base_h) || base_h <= 0) {
      if (is.finite(base_avg) && is.finite(base_ab) && base_ab > 0) {
        base_h <- base_avg * base_ab
      }
    }
    if (!is.finite(base_avg) || base_avg <= 0) {
      if (is.finite(base_h) && is.finite(base_ab) && base_ab > 0) {
        base_avg <- base_h / base_ab
      } else {
        base_avg <- NA_real_
      }
    }
    if (!is.finite(base_bb)) {
      base_bb <- 0
    }
    if (!is.finite(base_obp) || base_obp <= 0) {
      if (is.finite(base_h) && is.finite(base_bb) && is.finite(base_pa) && base_pa > 0) {
        base_obp <- (base_h + base_bb) / base_pa
      } else {
        base_obp <- NA_real_
      }
    }

    budget_bats <- as_num_safe(input$total_budget, 260) *
      as_num_safe(input$hitter_budget_share, 0.70) *
      as_num_safe(input$num_teams, 12)
    starter_count <- as.integer(as.numeric(input$num_teams) * sum(cfg()$projection$league$hitter_slots, na.rm = TRUE))
    numstartingbats <- min(max(1L, starter_count), nrow(src))
    dollars_per_slot <- budget_bats / numstartingbats
    min_bid <- as_num_safe(input$min_bid, 1)

    z_pool <- suppressWarnings(as.numeric(src$z_total_weights))
    avg_positive_z <- mean(z_pool[z_pool >= 0], na.rm = TRUE)
    if (!is.finite(avg_positive_z) || abs(avg_positive_z) < .Machine$double.eps^0.5) {
      avg_positive_z <- mean(z_pool, na.rm = TRUE)
    }
    if (!is.finite(base_z) && is.finite(base_dollars) && is.finite(avg_positive_z) && is.finite(dollars_per_slot) && abs(dollars_per_slot) > 0) {
      base_z <- ((base_dollars - min_bid) / dollars_per_slot) * avg_positive_z
    }
    if (!is.finite(base_z)) {
      return(list(data = data.frame(), message = "Unable to derive baseline z-total for this hitter."))
    }

    calc_z_per_unit <- function(stat_vec, z_vec, anchor_idx = 2L) {
      stat_vec <- suppressWarnings(as.numeric(stat_vec))
      z_vec <- suppressWarnings(as.numeric(z_vec))
      ok <- is.finite(stat_vec) & is.finite(z_vec)
      if (sum(ok) < 2) return(0)
      stat_ok <- stat_vec[ok]
      z_ok <- z_vec[ok]
      ord <- order(-stat_ok, na.last = TRUE)
      stat_ord <- stat_ok[ord]
      z_ord <- z_ok[ord]
      use_idx <- min(max(2L, as.integer(anchor_idx)), length(stat_ord))
      ds <- stat_ord[1] - stat_ord[use_idx]
      dz <- z_ord[1] - z_ord[use_idx]
      if (is.finite(ds) && abs(ds) > .Machine$double.eps^0.5 && is.finite(dz)) {
        return(dz / ds)
      }
      fit <- tryCatch(stats::lm(z_ok ~ stat_ok), error = function(e) NULL)
      if (!is.null(fit)) {
        coef_v <- suppressWarnings(as.numeric(stats::coef(fit)[2]))
        if (is.finite(coef_v)) return(coef_v)
      }
      0
    }

    category_keys <- active_hitter_categories()
    contribution_map <- list(
      hr = list(stat = "HR", base = base_hr, z_per = calc_z_per_unit(src$hr, src$hr_z, anchor_idx = 2L)),
      sb = list(stat = "SB", base = base_sb, z_per = calc_z_per_unit(src$sb, src$sb_z, anchor_idx = 2L)),
      r = list(stat = "R", base = base_r, z_per = calc_z_per_unit(src$r, src$r_z, anchor_idx = 2L)),
      rbi = list(stat = "RBI", base = base_rbi, z_per = calc_z_per_unit(src$rbi, src$rbi_z, anchor_idx = 3L)),
      avg = list(stat = "AVG", base = base_avg, z_per = calc_z_per_unit(src$avg, src$avg_z, anchor_idx = 2L)),
      obp = list(stat = "OBP", base = base_obp, z_per = calc_z_per_unit(src$obp, src$obp_z, anchor_idx = 2L))
    )
    category_keys <- category_keys[category_keys %in% names(contribution_map)]

    project_row <- function(pa_value, label, weight = NA_real_) {
      rate_mult <- pa_value / base_pa
      ab <- base_ab * rate_mult
      h <- base_h * rate_mult
      bb <- base_bb * rate_mult
      hr <- base_hr * rate_mult
      sb <- base_sb * rate_mult
      r <- base_r * rate_mult
      rbi <- base_rbi * rate_mult
      avg <- if (is.finite(ab) && ab > 0) (h / ab) else base_avg
      obp <- if (is.finite(pa_value) && pa_value > 0) ((h + bb) / pa_value) else base_obp

      stat_values <- c(HR = hr, SB = sb, R = r, RBI = rbi, AVG = avg, OBP = obp)
      z_delta <- 0
      for (k in category_keys) {
        conf <- contribution_map[[k]]
        v <- stat_values[[conf$stat]]
        if (is.finite(v) && is.finite(conf$base) && is.finite(conf$z_per)) {
          z_delta <- z_delta + (v - conf$base) * conf$z_per
        }
      }
      z_total <- base_z + z_delta

      dollars <- if (is.finite(avg_positive_z) && abs(avg_positive_z) > .Machine$double.eps^0.5) {
        (dollars_per_slot * (z_total / avg_positive_z)) + min_bid
      } else {
        NA_real_
      }

      data.frame(
        Scenario = label,
        Weight = weight,
        PA = pa_value,
        AB = ab,
        H = h,
        BB = bb,
        AVG = avg,
        OBP = obp,
        HR = hr,
        SB = sb,
        R = r,
        RBI = rbi,
        `z_total_weights` = z_total,
        `dollars_weights` = dollars,
        stringsAsFactors = FALSE,
        check.names = FALSE
      )
    }

    baseline_row <- project_row(base_pa, "Baseline (Proj PA)")
    if (is.finite(base_dollars)) {
      baseline_row$`dollars_weights` <- base_dollars
    }
    threshold_rows <- lapply(seq_along(pa_targets), function(i) {
      project_row(pa_targets[[i]], sprintf("PA %s", round(pa_targets[[i]], 0)), weight = weights[[i]])
    })
    threshold_df <- do.call(rbind, threshold_rows)
    weighted_pa <- sum(pa_targets * weights, na.rm = TRUE)

    weighted_stats <- c(
      AB = sum(threshold_df$AB * weights, na.rm = TRUE),
      H = sum(threshold_df$H * weights, na.rm = TRUE),
      BB = sum(threshold_df$BB * weights, na.rm = TRUE),
      HR = sum(threshold_df$HR * weights, na.rm = TRUE),
      SB = sum(threshold_df$SB * weights, na.rm = TRUE),
      R = sum(threshold_df$R * weights, na.rm = TRUE),
      RBI = sum(threshold_df$RBI * weights, na.rm = TRUE)
    )
    weighted_avg <- if (is.finite(weighted_stats[["AB"]]) && weighted_stats[["AB"]] > 0) {
      weighted_stats[["H"]] / weighted_stats[["AB"]]
    } else {
      base_avg
    }
    weighted_obp <- if (is.finite(weighted_pa) && weighted_pa > 0) {
      (weighted_stats[["H"]] + weighted_stats[["BB"]]) / weighted_pa
    } else {
      base_obp
    }
    weighted_stat_values <- c(
      HR = weighted_stats[["HR"]],
      SB = weighted_stats[["SB"]],
      R = weighted_stats[["R"]],
      RBI = weighted_stats[["RBI"]],
      AVG = weighted_avg,
      OBP = weighted_obp
    )
    weighted_z_delta <- 0
    for (k in category_keys) {
      conf <- contribution_map[[k]]
      v <- weighted_stat_values[[conf$stat]]
      if (is.finite(v) && is.finite(conf$base) && is.finite(conf$z_per)) {
        weighted_z_delta <- weighted_z_delta + (v - conf$base) * conf$z_per
      }
    }
    weighted_z <- base_z + weighted_z_delta
    weighted_dollars <- if (is.finite(avg_positive_z) && abs(avg_positive_z) > .Machine$double.eps^0.5) {
      (dollars_per_slot * (weighted_z / avg_positive_z)) + min_bid
    } else {
      NA_real_
    }
    weighted_row <- data.frame(
      Scenario = "Weighted PA Mix",
      Weight = 1,
      PA = weighted_pa,
      AB = weighted_stats[["AB"]],
      H = weighted_stats[["H"]],
      BB = weighted_stats[["BB"]],
      AVG = weighted_avg,
      OBP = weighted_obp,
      HR = weighted_stats[["HR"]],
      SB = weighted_stats[["SB"]],
      R = weighted_stats[["R"]],
      RBI = weighted_stats[["RBI"]],
      `z_total_weights` = weighted_z,
      `dollars_weights` = weighted_dollars,
      stringsAsFactors = FALSE,
      check.names = FALSE
    )

    out <- rbind(baseline_row, threshold_df, weighted_row)
    out$Weight[is.na(out$Weight)] <- NA_real_
    rownames(out) <- NULL

    list(
      data = out,
      message = "",
      player_label = sprintf("%s (%s)", p$player_name, p$team)
    )
  })

  comparison_hitters_data <- reactive({
    src <- hitter_source()
    keys <- unique(trimws(as.character(unlist(lapply(seq_len(5), function(i) input[[paste0("comparison_hitter_", i)]] %||% "")))))
    keys <- keys[nzchar(keys)]
    if (length(keys) == 0 || nrow(src) == 0) return(data.frame())
