    metric_cols <- get_selected_hitter_metric_columns(names(src), active_hitter_categories())$proj
    keep <- unique(c("player_name", "team", "position", "adp", "pa", metric_cols, "dollars_weights"))
    keep <- keep[keep %in% names(src)]
    out <- src[idx, keep, drop = FALSE]
    out <- out[order(-out$dollars_weights, out$adp, out$player_name, na.last = TRUE), , drop = FALSE]
    rownames(out) <- NULL
    out
  })

  comparison_pitchers_data <- reactive({
    src <- rv$pitcher_data
    if (is.null(src) || !is.data.frame(src) || nrow(src) == 0) return(data.frame())
    src$key <- make_player_key(src$player_name, src$team)
    keys <- unique(trimws(as.character(unlist(lapply(seq_len(5), function(i) input[[paste0("comparison_pitcher_", i)]] %||% "")))))
    keys <- keys[nzchar(keys)]
    if (length(keys) == 0 || nrow(src) == 0) return(data.frame())
    idx <- match(keys, src$key)
    idx <- idx[!is.na(idx)]
    if (length(idx) == 0) return(data.frame())
    out <- src[idx, , drop = FALSE]
    out <- out[, setdiff(names(out), "pitcher_role"), drop = FALSE]
    ord_adp <- if ("adp" %in% names(out)) suppressWarnings(as.numeric(out$adp)) else rep(NA_real_, nrow(out))
    ord_ip <- if ("proj_ip" %in% names(out)) suppressWarnings(as.numeric(out$proj_ip)) else rep(NA_real_, nrow(out))
    ord_name <- if ("player_name" %in% names(out)) as.character(out$player_name) else rep("", nrow(out))
    out <- out[order(ord_adp, -ord_ip, ord_name, na.last = TRUE), , drop = FALSE]
    rownames(out) <- NULL
    out
  })

