  get_hitter_choices_for_slot <- function(slot_code) {
    pool <- adp_suggestion_pool()
    if (nrow(pool) == 0) return(stats::setNames("", ""))
    keep <- pool_matches_hitter_slot(pool$positions, slot_code)
    pool <- pool[keep, , drop = FALSE]
    c(stats::setNames("", ""), stats::setNames(pool$key, pool$label))
  }

