        rid <- paste0("team_h_round_", i)
        oid <- paste0("team_h_overall_", i)
        seeded_row <- i <= length(seed_rows)
        seed <- if (seeded_row) seed_rows[[i]] else list()
        sel <- isolate(input[[pid]])
        rnd <- isolate(input[[rid]])
        opk <- isolate(input[[oid]])
        sel_empty <- is.null(sel) || !nzchar(trimws(as.character(sel)))
