      ADP = rep(NA_real_, n_slots),
      AB = rep(NA_real_, n_slots),
      PA = rep(NA_real_, n_slots),
      H = rep(NA_real_, n_slots),
      BB = rep(NA_real_, n_slots),
      HR = rep(NA_real_, n_slots),
      SB = rep(NA_real_, n_slots),
      R = rep(NA_real_, n_slots),
      RBI = rep(NA_real_, n_slots),
      AVG = rep(NA_real_, n_slots),
      OBP = rep(NA_real_, n_slots),
      Dollars.Weights = rep(NA_real_, n_slots),
      Round = rep(NA_real_, n_slots),
      `Overall Pick` = rep(NA_real_, n_slots),
      `Min` = rep(NA_real_, n_slots),
      `Max` = rep(NA_real_, n_slots),
      stringsAsFactors = FALSE,
      check.names = FALSE
    )
    if (nrow(out) == 0) return(out)

    for (i in seq_len(nrow(out))) {
      pid <- paste0("team_h_player_", i)
      rid <- paste0("team_h_round_", i)
      oid <- paste0("team_h_overall_", i)
      raw_player_value <- as.character(input[[pid]] %||% "")
      round_value <- as_num_safe(input[[rid]], NA_real_)
      overall_value <- as_num_safe(input[[oid]], NA_real_)
      overall_auto <- compute_snake_overall_pick(round_value, as_int_safe(input$team_league_teams, 12L), as_int_safe(input$team_draft_position, 1L))
      key <- resolve_player_key(raw_player_value, src)
      idx <- match(key, src$key)
      if (!is.na(idx)) {
        out$Player[i] <- src$player_name[idx]
        out$Team[i] <- src$team[idx]
        out$ADP[i] <- src$adp[idx]
        out$AB[i] <- src$ab[idx]
        out$PA[i] <- src$pa[idx]
        out$H[i] <- src$h[idx]
        out$BB[i] <- src$bb[idx]
        out$HR[i] <- src$hr[idx]
        out$SB[i] <- src$sb[idx]
        out$R[i] <- src$r[idx]
        out$RBI[i] <- src$rbi[idx]
        out$AVG[i] <- src$avg[idx]
        out$OBP[i] <- src$obp[idx]
        out$Dollars.Weights[i] <- src$dollars_weights[idx]
        out$`Min`[i] <- src$adp_min_pick[idx]
        out$`Max`[i] <- src$adp_max_pick[idx]
      } else if (nzchar(trimws(raw_player_value))) {
        parsed <- parse_manual_player_entry(raw_player_value)
        out$Player[i] <- parsed$name
        out$Team[i] <- parsed$team
      }
      out$Round[i] <- round_value
      out$`Overall Pick`[i] <- if (is.na(overall_auto)) overall_value else overall_auto
    }
    out
  })

