  build_team_import_export_payload <- function() {
    h_slots <- hitter_slots()
    p_slots <- pitcher_slots()
    b_slots <- bench_slots()
    draft_teams <- as_int_safe(input$team_league_teams, 12L)
    draft_position <- as_int_safe(input$team_draft_position, 1L)

    collect_rows <- function(prefix, slots) {
      lapply(seq_along(slots), function(i) {
        pid <- paste0(prefix, "_player_", i)
        rid <- paste0(prefix, "_round_", i)
        oid <- paste0(prefix, "_overall_", i)
        round_value <- as_num_safe(input[[rid]], NA_real_)
        overall_manual <- as_num_safe(input[[oid]], NA_real_)
        overall_auto <- compute_snake_overall_pick(round_value, draft_teams, draft_position)
        list(
          slot = as.character(slots[[i]]),
          player_input = as.character(input[[pid]] %||% ""),
          round = round_value,
          overall_pick = if (is.na(overall_auto)) overall_manual else overall_auto
        )
      })
    }

    list(
      schema = "team_importer_v1",
      exported_at_utc = format(Sys.time(), "%Y-%m-%dT%H:%M:%SZ", tz = "UTC"),
      roster_setup = list(
        preset = as.character(input$team_roster_preset %||% "Custom"),
        team_c = as_int_safe(input$team_c, 0L),
        team_1b = as_int_safe(input$team_1b, 0L),
        team_2b = as_int_safe(input$team_2b, 0L),
        team_ss = as_int_safe(input$team_ss, 0L),
        team_3b = as_int_safe(input$team_3b, 0L),
        team_of = as_int_safe(input$team_of, 0L),
        team_mi = as_int_safe(input$team_mi, 0L),
        team_ci = as_int_safe(input$team_ci, 0L),
        team_if = as_int_safe(input$team_if, 0L),
        team_ut = as_int_safe(input$team_ut, 0L),
        team_sp = as_int_safe(input$team_sp, 0L),
        team_rp = as_int_safe(input$team_rp, 0L),
        team_p = as_int_safe(input$team_p, 0L),
        team_bench = as_int_safe(input$team_bench, 0L),
        team_league_teams = draft_teams,
        team_draft_position = draft_position
      ),
      hitters = collect_rows("team_h", h_slots),
      pitchers = collect_rows("team_p", p_slots),
      bench = collect_rows("team_b", b_slots)
    )
  }

  apply_team_import_payload <- function(payload) {
    roster <- payload$roster_setup
    if (!is.list(roster)) {
      stop("Missing roster_setup section in import file.")
    }

    updateSelectInput(session, "team_roster_preset", selected = "Custom")
    updateNumericInput(session, "team_c", value = as_int_safe(roster$team_c, as_int_safe(input$team_c, 0L)))
    updateNumericInput(session, "team_1b", value = as_int_safe(roster$team_1b, as_int_safe(input$team_1b, 0L)))
    updateNumericInput(session, "team_2b", value = as_int_safe(roster$team_2b, as_int_safe(input$team_2b, 0L)))
    updateNumericInput(session, "team_ss", value = as_int_safe(roster$team_ss, as_int_safe(input$team_ss, 0L)))
    updateNumericInput(session, "team_3b", value = as_int_safe(roster$team_3b, as_int_safe(input$team_3b, 0L)))
    updateNumericInput(session, "team_of", value = as_int_safe(roster$team_of, as_int_safe(input$team_of, 0L)))
    updateNumericInput(session, "team_mi", value = as_int_safe(roster$team_mi, as_int_safe(input$team_mi, 0L)))
    updateNumericInput(session, "team_ci", value = as_int_safe(roster$team_ci, as_int_safe(input$team_ci, 0L)))
    updateNumericInput(session, "team_if", value = as_int_safe(roster$team_if, as_int_safe(input$team_if, 0L)))
    updateNumericInput(session, "team_ut", value = as_int_safe(roster$team_ut, as_int_safe(input$team_ut, 0L)))
    updateNumericInput(session, "team_sp", value = as_int_safe(roster$team_sp, as_int_safe(input$team_sp, 0L)))
    updateNumericInput(session, "team_rp", value = as_int_safe(roster$team_rp, as_int_safe(input$team_rp, 0L)))
    updateNumericInput(session, "team_p", value = as_int_safe(roster$team_p, as_int_safe(input$team_p, 0L)))
    updateNumericInput(session, "team_bench", value = as_int_safe(roster$team_bench, as_int_safe(input$team_bench, 0L)))
    updateNumericInput(session, "team_league_teams", value = as_int_safe(roster$team_league_teams, as_int_safe(input$team_league_teams, 12L)))
    updateNumericInput(session, "team_draft_position", value = as_int_safe(roster$team_draft_position, as_int_safe(input$team_draft_position, 1L)))

    h_src <- hitter_source()
    p_src <- pitcher_source()
    b_src <- bench_source()
    adp_src <- adp_lookup()

    resolve_for_pool <- function(raw_value, src) {
      val <- as.character(raw_value %||% "")
      if (!nzchar(trimws(val))) return("")
      key <- resolve_player_key(val, src)
      if (nzchar(key)) return(key)
      # Secondary resolution against ADP pool to avoid preserving raw "name|TEAM".
      key_adp <- resolve_player_key(val, adp_src)
      if (nzchar(key_adp)) return(key_adp)

      parsed <- parse_manual_player_entry(val)
      if (nzchar(parsed$name) && nzchar(parsed$team)) {
        return(sprintf("%s (%s)", tools::toTitleCase(parsed$name), parsed$team))
      }
      if (nzchar(parsed$name)) {
        return(tools::toTitleCase(parsed$name))
      }
      val
    }

    build_seed_rows <- function(rows, n_slots, src) {
      n_slots <- max(0L, as.integer(n_slots))
      out <- vector("list", n_slots)
      if (n_slots == 0L) return(out)
      rows <- rows %||% list()
      for (i in seq_len(n_slots)) {
        row <- if (i <= length(rows)) rows[[i]] else list()
        out[[i]] <- list(
          player = resolve_for_pool(row$player_input %||% "", src),
          round = as_num_safe(row$round, NA_real_),
          overall_pick = as_num_safe(row$overall_pick, NA_real_)
        )
      }
      out
    }

    hitter_slot_count <- as_int_safe(roster$team_c, 0L) +
      as_int_safe(roster$team_1b, 0L) +
      as_int_safe(roster$team_2b, 0L) +
      as_int_safe(roster$team_ss, 0L) +
      as_int_safe(roster$team_3b, 0L) +
      as_int_safe(roster$team_of, 0L) +
      as_int_safe(roster$team_mi, 0L) +
      as_int_safe(roster$team_ci, 0L) +
      as_int_safe(roster$team_if, 0L) +
      as_int_safe(roster$team_ut, 0L)
    pitcher_slot_count <- as_int_safe(roster$team_sp, 0L) +
      as_int_safe(roster$team_rp, 0L) +
      as_int_safe(roster$team_p, 0L)
    bench_slot_count <- as_int_safe(roster$team_bench, 0L)

    rv$team_import_seed <- list(
      hitters = build_seed_rows(payload$hitters, hitter_slot_count, h_src),
      pitchers = build_seed_rows(payload$pitchers, pitcher_slot_count, p_src),
      bench = build_seed_rows(payload$bench, bench_slot_count, b_src)
    )
    rv$team_import_seed_force <- TRUE

    # Force seed use for immediate redraw; then relax to "fill if blank/NA".
    session$onFlushed(function() {
      rv$team_import_seed_force <- FALSE
    }, once = TRUE)
  }

  historical_targets <- reactive({
    read_cached_historical_targets(cfg())
  })

  active_target_draft_label <- reactive({
    from_run <- resolve_historical_target_draft_label(
      get_run_metric_value(rv$run_data, "Draft Type", default = "")
    )
    if (nzchar(from_run)) return(from_run)
    resolve_historical_target_draft_label(as.character(input$adp_draft_type %||% ""))
  })

  selected_historical_target <- reactive({
    dat <- historical_targets()
    if (is.null(dat) || !is.data.frame(dat) || nrow(dat) == 0) return(NULL)
    draft_types <- tolower(as.character(dat$Draft.Type))
    league_teams <- as_int_safe(input$team_league_teams, as_int_safe(input$num_teams, 0L))
    preferred <- character(0)
    if (league_teams == 15L) {
      preferred <- c("Main Event")
    } else if (league_teams == 12L) {
      preferred <- c("Online Championship", "NFBC 50")
    }
    fallback_label <- active_target_draft_label()
    if (nzchar(fallback_label)) {
      preferred <- c(preferred, fallback_label)
    }
    preferred <- unique(preferred[nzchar(preferred)])
    if (length(preferred) == 0) return(NULL)
    for (lbl in preferred) {
      idx <- match(tolower(lbl), draft_types)
      if (!is.na(idx)) return(dat[idx, , drop = FALSE])
    }
    NULL
  })

  team_hitter_totals <- reactive({
    dat <- team_hitters_data()
    if (nrow(dat) == 0) {
      return(list(
        hitter_slots = length(hitter_slots()),
        hitter_filled = 0L,
        ab = NA_real_, pa = NA_real_, hr = NA_real_, sb = NA_real_,
        r = NA_real_, rbi = NA_real_, avg = NA_real_, dollars = NA_real_
      ))
    }

    ab_vals <- suppressWarnings(as.numeric(dat$AB))
    pa_vals <- suppressWarnings(as.numeric(dat$PA))
    h_vals <- suppressWarnings(as.numeric(dat$H))
    hr_vals <- suppressWarnings(as.numeric(dat$HR))
    sb_vals <- suppressWarnings(as.numeric(dat$SB))
    r_vals <- suppressWarnings(as.numeric(dat$R))
    rbi_vals <- suppressWarnings(as.numeric(dat$RBI))
    avg_vals <- suppressWarnings(as.numeric(dat$AVG))
    dollars_vals <- suppressWarnings(as.numeric(dat$Dollars.Weights))

    ab <- if (any(!is.na(ab_vals))) sum(ab_vals, na.rm = TRUE) else NA_real_
    pa <- if (any(!is.na(pa_vals))) sum(pa_vals, na.rm = TRUE) else NA_real_
    hr <- if (any(!is.na(hr_vals))) sum(hr_vals, na.rm = TRUE) else NA_real_
    sb <- if (any(!is.na(sb_vals))) sum(sb_vals, na.rm = TRUE) else NA_real_
    runs <- if (any(!is.na(r_vals))) sum(r_vals, na.rm = TRUE) else NA_real_
    rbi <- if (any(!is.na(rbi_vals))) sum(rbi_vals, na.rm = TRUE) else NA_real_
    dollars <- if (any(!is.na(dollars_vals))) sum(dollars_vals, na.rm = TRUE) else NA_real_

    avg <- NA_real_
    if (any(!is.na(h_vals)) && !is.na(ab) && is.finite(ab) && ab > 0) {
      avg <- sum(h_vals, na.rm = TRUE) / ab
    } else if (!is.na(pa) && is.finite(pa) && pa > 0) {
      avg <- sum(pa_vals * avg_vals, na.rm = TRUE) / pa
    }

    filled_hitters <- sum(nzchar(trimws(as.character(dat$Player %||% rep("", nrow(dat))))))

    list(
      hitter_slots = length(hitter_slots()),
      hitter_filled = as.integer(filled_hitters),
      ab = ab,
      pa = pa,
      hr = hr,
      sb = sb,
      r = runs,
      rbi = rbi,
      avg = avg,
      dollars = dollars
    )
  })

  team_pitcher_totals <- reactive({
    dat <- team_pitchers_data()
    if (nrow(dat) == 0) {
      return(list(ip = NA_real_, w = NA_real_, k = NA_real_, sv = NA_real_, era = NA_real_, whip = NA_real_))
    }

    ip_vals <- suppressWarnings(as.numeric(dat$`Proj IP`))
    w_vals <- suppressWarnings(as.numeric(dat$`Proj W`))
    k_vals <- suppressWarnings(as.numeric(dat$`Proj K`))
    sv_vals <- suppressWarnings(as.numeric(dat$`Proj SV`))
    era_vals <- suppressWarnings(as.numeric(dat$`Proj ERA`))
    whip_vals <- suppressWarnings(as.numeric(dat$`Proj WHIP`))

    ip <- if (any(!is.na(ip_vals))) sum(ip_vals, na.rm = TRUE) else NA_real_
    w <- if (any(!is.na(w_vals))) sum(w_vals, na.rm = TRUE) else NA_real_
    k <- if (any(!is.na(k_vals))) sum(k_vals, na.rm = TRUE) else NA_real_
    sv <- if (any(!is.na(sv_vals))) sum(sv_vals, na.rm = TRUE) else NA_real_
    era <- if (!is.na(ip) && is.finite(ip) && ip > 0) sum(ip_vals * era_vals, na.rm = TRUE) / ip else NA_real_
    whip <- if (!is.na(ip) && is.finite(ip) && ip > 0) sum(ip_vals * whip_vals, na.rm = TRUE) / ip else NA_real_

    list(ip = ip, w = w, k = k, sv = sv, era = era, whip = whip)
  })

