  output$team_targets_totals <- renderUI({
    target <- selected_historical_target()
    if (is.null(target) || nrow(target) == 0) {
      return(tags$div(class = "status-shell subtle-note", "No matching historical targets found for the current ADP draft type."))
    }

    hit <- team_hitter_totals()
    pit <- team_pitcher_totals()
    hitter_slots_total <- as.integer(max(0L, hit$hitter_slots))
    hitter_filled_n <- as.integer(max(0L, hit$hitter_filled))

    tv <- function(name) suppressWarnings(as.numeric(target[[name]][1]))
    t_ab <- tv("AB")
    t_r <- tv("R")
    t_hr <- tv("HR")
    t_rbi <- tv("RBI")
    t_sb <- tv("SB")
    t_avg <- tv("AVG")
    t_k <- tv("K")
    t_w <- tv("W")
    t_sv <- tv("SV")
    t_era <- tv("ERA")
    t_whip <- tv("WHIP")
    t_ip <- tv("IP")

    fmt_team <- function(x, ratio = FALSE) {
      if (is.na(x)) return("--")
      if (isTRUE(ratio)) sprintf("%.3f", x) else sprintf("%.1f", x)
    }
    fmt_target <- function(x, ratio = FALSE) {
      if (is.na(x)) return("--")
      if (isTRUE(ratio)) sprintf("%.3f", x) else sprintf("%.1f", x)
    }
    fmt_gap <- function(x, ratio = FALSE) {
      if (is.na(x)) return("--")
      if (isTRUE(ratio)) sprintf("%+.3f", x) else sprintf("%+.1f", x)
    }
    fmt_per <- function(x) {
      if (is.na(x)) return("--")
      sprintf("%.1f", x)
    }

    hitters_rows <- data.frame(
      Category = c("AB", "R", "HR", "RBI", "SB", "AVG"),
      Team = c(hit$ab, hit$r, hit$hr, hit$rbi, hit$sb, hit$avg),
      Target = c(t_ab, t_r, t_hr, t_rbi, t_sb, t_avg),
      stringsAsFactors = FALSE
    )
    hitters_rows$Gap <- hitters_rows$Team - hitters_rows$Target
    hitters_rows$PerHitterTeam <- if (hitter_filled_n > 0) hitters_rows$Team / hitter_filled_n else NA_real_
    hitters_rows$PerHitterTarget <- if (hitter_slots_total > 0) hitters_rows$Target / hitter_slots_total else NA_real_

    pitchers_rows <- data.frame(
      Category = c("IP", "W", "K", "SV", "ERA", "WHIP"),
      Team = c(pit$ip, pit$w, pit$k, pit$sv, pit$era, pit$whip),
      Target = c(t_ip, t_w, t_k, t_sv, t_era, t_whip),
      stringsAsFactors = FALSE
    )
    pitchers_rows$Gap <- pitchers_rows$Team - pitchers_rows$Target

    tags$div(
      class = "team-totals-wrapper",
      tags$div(
        class = "team-total-line",
        tags$span(tags$strong("Target Set: "), as.character(target$Draft.Type[1])),
        tags$span(tags$strong("Hitters Filled: "), sprintf("%d / %d", hitter_filled_n, hitter_slots_total)),
        if (!identical(as.character(target$Draft.Type[1]), "Main Event"))
          tags$span(class = "subtle-note", style = "font-style: italic;",
            "\u2014 AVG target sourced from Main Event 2025 (OC/NFBC 50 standings not available)")
        else
          tags$span(class = "subtle-note", style = "font-style: italic;",
            "\u2014 Targets: NFBC Main Event 2025, 80th percentile (N\u00a0=\u00a0855)")
      ),
      tags$div(
        class = "team-totals-tables",
        tags$div(
          class = "team-totals-section",
          tags$h6(class = "team-totals-heading", "Hitter Target Check"),
          tags$table(
            class = "table table-sm table-striped",
            tags$thead(tags$tr(
              tags$th("Category"),
              tags$th("Team"),
              tags$th("Target"),
              tags$th("Gap"),
              tags$th("Team / Hitter"),
              tags$th("Target / Hitter")
            )),
            tags$tbody(lapply(seq_len(nrow(hitters_rows)), function(i) {
              is_rate <- hitters_rows$Category[i] %in% c("AVG", "OBP")
              tags$tr(
                tags$td(hitters_rows$Category[i]),
                tags$td(fmt_team(hitters_rows$Team[i], ratio = is_rate)),
                tags$td(fmt_target(hitters_rows$Target[i], ratio = is_rate)),
                tags$td(if (is_rate) fmt_gap(hitters_rows$Gap[i], ratio = TRUE) else fmt_gap(hitters_rows$Gap[i])),
                tags$td(if (is_rate) fmt_team(hitters_rows$Team[i], ratio = TRUE) else fmt_per(hitters_rows$PerHitterTeam[i])),
                tags$td(if (is_rate) fmt_target(hitters_rows$Target[i], ratio = TRUE) else fmt_per(hitters_rows$PerHitterTarget[i]))
              )
            }))
          )
        ),
        tags$div(
          class = "team-totals-section",
          tags$h6(class = "team-totals-heading", "Pitcher Target Check"),
          tags$table(
            class = "table table-sm table-striped",
            tags$thead(tags$tr(
              tags$th("Category"),
              tags$th("Team"),
              tags$th("Target"),
              tags$th("Gap")
            )),
            tags$tbody(lapply(seq_len(nrow(pitchers_rows)), function(i) {
              ratio <- pitchers_rows$Category[i] %in% c("ERA", "WHIP")
              tags$tr(
                tags$td(pitchers_rows$Category[i]),
                tags$td(fmt_team(pitchers_rows$Team[i], ratio = ratio)),
                tags$td(fmt_target(pitchers_rows$Target[i], ratio = ratio)),
                tags$td(fmt_gap(pitchers_rows$Gap[i], ratio = ratio))
              )
            }))
          )
        )
      )
    )
  })

