    rv$team_import_status <- "No team import loaded."
    showNotification("Team Importer inputs cleared.", type = "message", duration = 3)
  })

  observeEvent(input$team_import, {
    req(input$team_import$datapath)
    on.exit({
      session$sendCustomMessage("cleanup-ui-backdrops", list())
    }, add = TRUE)
    import_name <- coalesce_chr(input$team_import$name, "")
    if (!grepl("\\.json$", tolower(import_name))) {
      rv$team_import_status <- "Import failed: use a .json export file."
      showNotification("Import failed: use a .json team export file.", type = "error", duration = 8)
      return()
    }
    imported <- tryCatch({
      txt <- paste(readLines(input$team_import$datapath, warn = FALSE, encoding = "UTF-8"), collapse = "\n")
      jsonlite::fromJSON(txt, simplifyVector = FALSE)
    }, error = function(e) e)

    if (inherits(imported, "error") || !is.list(imported)) {
      rv$team_import_status <- "Import failed: invalid file format."
      showNotification("Failed to import team file. Please use a valid exported .json file.", type = "error", duration = 8)
      return()
    }
    if (!identical(as.character(imported$schema %||% ""), "team_importer_v1")) {
      rv$team_import_status <- "Import failed: unsupported schema."
      showNotification("Unsupported import format.", type = "error", duration = 8)
      return()
    }

    hitters_n <- length(imported$hitters %||% list())
    pitchers_n <- length(imported$pitchers %||% list())
    bench_n <- length(imported$bench %||% list())
    if ((hitters_n + pitchers_n + bench_n) > 200) {
      rv$team_import_status <- "Import failed: file has too many rows."
      showNotification("Import file is larger than supported for web import.", type = "error", duration = 8)
      return()
    }

    applied <- tryCatch({
      apply_team_import_payload(imported)
      TRUE
    }, error = function(e) e)

    if (inherits(applied, "error")) {
      rv$team_import_status <- sprintf("Import failed: %s", conditionMessage(applied))
      showNotification(
        sprintf("Import failed: %s", conditionMessage(applied)),
        type = "error",
        duration = 8
      )
      return()
    }

    rv$team_import_status <- sprintf(
      "Import successful: %s (%s)",
      format(Sys.time(), "%Y-%m-%d %H:%M:%S %Z"),
      coalesce_chr(input$team_import$name, "team_import.json")
    )
  })

