      hr = as_num_safe(input$sw_hr, 0),
      sb = as_num_safe(input$sw_sb, 0),
      avg = as_num_safe(input$sw_avg, 0),
      r = as_num_safe(input$sw_r, 0),
      rbi = as_num_safe(input$sw_rbi, 0),
      obp = as_num_safe(input$sw_obp, 0)
    )
    w[!is.finite(w)] <- 0
    w
  })

  valued_hitter_output <- reactive({
    dat <- rv$output_data
    if (is.null(dat) || !is.data.frame(dat) || nrow(dat) == 0) {
      return(dat)
    }
    dat <- fill_missing_hitter_positions(dat, rv$adp_data)
    revalue_hitter_output(
      dat = dat,
      selected_categories = active_hitter_categories(),
      stat_weights = active_hitter_stat_weights(),
      pa_weight = as_num_safe(input$sw_pa, 0),
      z_source = rv$hitter_zscores,
      num_teams = input$num_teams,
      total_budget = input$total_budget,
      hitter_budget_share = input$hitter_budget_share,
      min_bid = input$min_bid,
      starter_slots_per_team = sum(cfg()$projection$league$hitter_slots, na.rm = TRUE)
    )
  })

  filter_hitter_output_positions <- function(dat, selected_positions) {
    if (is.null(dat) || !is.data.frame(dat) || nrow(dat) == 0) {
      return(dat)
    }
    selected <- toupper(as.character(selected_positions %||% character(0)))
    # No positions selected → show nothing (consistent with ADP filter behaviour)
    if (length(selected) == 0) {
      return(dat[0L, , drop = FALSE])
    }
    pos_col <- intersect(c("position", "positions", "Position", "Position(s)"), names(dat))
    if (length(pos_col) == 0) {
      return(dat)
    }
    keep <- row_has_any_position(dat[[pos_col[1]]], selected)
    dat[keep, , drop = FALSE]
  }

  filtered_hitter_full_output <- reactive({
    filter_hitter_output_positions(valued_hitter_output(), input$hitter_output_pos_filter_full)
  })

  filtered_hitter_proj_output <- reactive({
    filter_hitter_output_positions(valued_hitter_output(), input$hitter_output_pos_filter_proj)
  })

  filtered_hitter_z_output <- reactive({
    filter_hitter_output_positions(valued_hitter_output(), input$hitter_output_pos_filter_z)
  })

  slice_hitter_tables <- function(dat) {
    if (is.null(dat) || !is.data.frame(dat) || nrow(dat) == 0) {
      return(list(full = dat, proj = dat, z = dat))
    }
    metric_cols <- get_selected_hitter_metric_columns(names(dat), active_hitter_categories())
    id_cols <- intersect(c("player_name", "team", "position", "adp", "pa"), names(dat))
    full_extra <- intersect(c("z_total_raw", "z_total_weights", "dollars_raw", "dollars_weights", "dollars_adp"), names(dat))
    z_totals <- intersect(c("z_total_raw", "z_total_weights"), names(dat))

    full_dat <- dat[, unique(c(id_cols, metric_cols$proj, metric_cols$z, full_extra)), drop = FALSE]
    proj_dat <- dat[, unique(c(id_cols, metric_cols$proj, intersect(c("dollars_raw", "dollars_weights", "dollars_adp"), names(dat)))), drop = FALSE]
    z_dat <- dat[, unique(c(id_cols, metric_cols$z, z_totals)), drop = FALSE]

    list(full = full_dat, proj = proj_dat, z = z_dat)
  }

  clear_dt_filters <- function(output_id, dat) {
    if (is.null(dat) || !is.data.frame(dat)) {
      return(invisible(NULL))
    }
    proxy <- dataTableProxy(outputId = output_id)
    updateSearch(proxy, keywords = list(global = "", columns = rep("", ncol(dat) + 1L)))
    session$sendCustomMessage("dt-range-filter-clear", list(id = output_id))
    invisible(NULL)
  }

  observeEvent(input$reset_table_filters, {
    hitter_slices <- slice_hitter_tables(valued_hitter_output())
    clear_dt_filters("full_table", hitter_slices$full)
    clear_dt_filters("proj_table", hitter_slices$proj)
    clear_dt_filters("z_table", hitter_slices$z)

    clear_dt_filters("pitcher_sp_skillz_table", rv$pitcher_sp_skillz)
    clear_dt_filters("pitcher_table", rv$pitcher_data)
    clear_dt_filters("adp_table", filtered_adp())

    showNotification("Table filters reset.", type = "message", duration = 3)
  })

