    if ("Eno" %in% names(disp)) disp$Eno <- fmt_num(disp$Eno, 0L)
    if ("CK" %in% names(disp)) disp$CK <- fmt_num(disp$CK, 0L)
    if ("DS" %in% names(disp)) disp$DS <- fmt_num(disp$DS, 0L)

    tags$div(
      class = "table-scroll-wrap",
      tags$table(
        class = "table table-sm table-striped",
        tags$thead(tags$tr(lapply(names(disp), tags$th))),
        tags$tbody(
          lapply(seq_len(nrow(disp)), function(i) {
            tags$tr(lapply(disp[i, , drop = FALSE], function(cell) tags$td(as.character(cell))))
          })
        )
      )
    )
  })

  output$team_hitters_table <- renderUI({
    dat <- team_hitters_data()
    if (is.null(dat) || !is.data.frame(dat) || nrow(dat) == 0) {
      return(tags$p(class = "subtle-note", "No hitter entries selected."))
    }

    selected_cats <- active_hitter_categories()
    metric_col_map <- c(
      hr = "HR",
      sb = "SB",
      r = "R",
      rbi = "RBI",
      avg = "AVG",
      obp = "OBP"
    )
    selected_metric_cols <- unname(metric_col_map[selected_cats])
    selected_metric_cols <- selected_metric_cols[!is.na(selected_metric_cols)]
    context_cols <- c("AB", "PA", "H")
    if ("obp" %in% selected_cats) {
      context_cols <- c(context_cols, "BB")
    }

    show_cols <- c(
      "Position", "Player", "Team", "ADP",
      context_cols, selected_metric_cols,
      "Dollars.Weights", "Round", "Overall Pick", "Min", "Max"
    )
    show_cols <- show_cols[show_cols %in% names(dat)]
    dat <- dat[, show_cols, drop = FALSE]

    fmt_num <- function(x, digits = 1L) {
      x_num <- suppressWarnings(as.numeric(x))
      ifelse(is.na(x_num), "", format(round(x_num, digits = digits), nsmall = digits, trim = TRUE, scientific = FALSE))
    }

    disp <- dat
    if ("ADP" %in% names(disp)) disp$ADP <- fmt_num(disp$ADP, 2L)
    if ("AB" %in% names(disp)) disp$AB <- fmt_num(disp$AB, 1L)
    if ("PA" %in% names(disp)) disp$PA <- fmt_num(disp$PA, 1L)
    if ("H" %in% names(disp)) disp$H <- fmt_num(disp$H, 1L)
    if ("BB" %in% names(disp)) disp$BB <- fmt_num(disp$BB, 1L)
    if ("HR" %in% names(disp)) disp$HR <- fmt_num(disp$HR, 1L)
    if ("SB" %in% names(disp)) disp$SB <- fmt_num(disp$SB, 1L)
    if ("R" %in% names(disp)) disp$R <- fmt_num(disp$R, 1L)
    if ("RBI" %in% names(disp)) disp$RBI <- fmt_num(disp$RBI, 1L)
    if ("AVG" %in% names(disp)) disp$AVG <- fmt_num(disp$AVG, 3L)
    if ("OBP" %in% names(disp)) disp$OBP <- fmt_num(disp$OBP, 3L)
    if ("Dollars.Weights" %in% names(disp)) disp$Dollars.Weights <- fmt_num(disp$Dollars.Weights, 2L)
    if ("Round" %in% names(disp)) disp$Round <- fmt_num(disp$Round, 0L)
    if ("Overall Pick" %in% names(disp)) disp$`Overall Pick` <- fmt_num(disp$`Overall Pick`, 0L)
    if ("Min" %in% names(disp)) disp$`Min` <- fmt_num(disp$`Min`, 0L)
    if ("Max" %in% names(disp)) disp$`Max` <- fmt_num(disp$`Max`, 0L)

    tags$div(
      class = "table-scroll-wrap",
      tags$table(
        class = "table table-sm table-striped",
        tags$thead(tags$tr(lapply(names(disp), tags$th))),
        tags$tbody(
          lapply(seq_len(nrow(disp)), function(i) {
            tags$tr(lapply(disp[i, , drop = FALSE], function(cell) tags$td(as.character(cell))))
          })
        )
      )
    )
  })

  output$team_pitchers_table <- renderUI({
    dat <- team_pitchers_data()
    if (is.null(dat) || !is.data.frame(dat) || nrow(dat) == 0) {
      return(tags$p(class = "subtle-note", "No pitcher entries selected."))
    }

    show_cols <- c(
      "Position", "Player", "Team", "ADP",
      "Proj IP", "Proj W", "Proj K", "Proj SV", "Proj ERA", "Proj WHIP",
      "Round", "Overall Pick", "Min", "Max"
    )
    show_cols <- show_cols[show_cols %in% names(dat)]
    dat <- dat[, show_cols, drop = FALSE]

    fmt_num <- function(x, digits = 1L) {
      x_num <- suppressWarnings(as.numeric(x))
      ifelse(is.na(x_num), "", format(round(x_num, digits = digits), nsmall = digits, trim = TRUE, scientific = FALSE))
    }

    disp <- dat
    if ("ADP" %in% names(disp)) disp$ADP <- fmt_num(disp$ADP, 2L)
    if ("Proj IP" %in% names(disp)) disp$`Proj IP` <- fmt_num(disp$`Proj IP`, 1L)
    if ("Proj W" %in% names(disp)) disp$`Proj W` <- fmt_num(disp$`Proj W`, 1L)
    if ("Proj K" %in% names(disp)) disp$`Proj K` <- fmt_num(disp$`Proj K`, 1L)
    if ("Proj SV" %in% names(disp)) disp$`Proj SV` <- fmt_num(disp$`Proj SV`, 1L)
    if ("Proj ERA" %in% names(disp)) disp$`Proj ERA` <- fmt_num(disp$`Proj ERA`, 3L)
    if ("Proj WHIP" %in% names(disp)) disp$`Proj WHIP` <- fmt_num(disp$`Proj WHIP`, 3L)
    if ("Round" %in% names(disp)) disp$Round <- fmt_num(disp$Round, 0L)
    if ("Overall Pick" %in% names(disp)) disp$`Overall Pick` <- fmt_num(disp$`Overall Pick`, 0L)
    if ("Min" %in% names(disp)) disp$Min <- fmt_num(disp$Min, 0L)
    if ("Max" %in% names(disp)) disp$Max <- fmt_num(disp$Max, 0L)

    tags$div(
      class = "table-scroll-wrap",
      tags$table(
        class = "table table-sm table-striped",
        tags$thead(tags$tr(lapply(names(disp), tags$th))),
        tags$tbody(
          lapply(seq_len(nrow(disp)), function(i) {
            tags$tr(lapply(disp[i, , drop = FALSE], function(cell) tags$td(as.character(cell))))
          })
        )
      )
    )
  })

  output$team_bench_table <- renderUI({
    dat <- team_bench_data()
    if (is.null(dat) || !is.data.frame(dat) || nrow(dat) == 0) {
      return(tags$p(class = "subtle-note", "No bench entries selected."))
    }

    show_cols <- c("Player", "Team", "Position", "ADP", "Round", "Overall Pick", "Min", "Max")
    show_cols <- show_cols[show_cols %in% names(dat)]
    dat <- dat[, show_cols, drop = FALSE]

    fmt_num <- function(x, digits = 1L) {
      x_num <- suppressWarnings(as.numeric(x))
      ifelse(is.na(x_num), "", format(round(x_num, digits = digits), nsmall = digits, trim = TRUE, scientific = FALSE))
    }

    disp <- dat
    if ("ADP" %in% names(disp)) disp$ADP <- fmt_num(disp$ADP, 2L)
    if ("Round" %in% names(disp)) disp$Round <- fmt_num(disp$Round, 0L)
    if ("Overall Pick" %in% names(disp)) disp$`Overall Pick` <- fmt_num(disp$`Overall Pick`, 0L)
    if ("Min" %in% names(disp)) disp$Min <- fmt_num(disp$Min, 0L)
    if ("Max" %in% names(disp)) disp$Max <- fmt_num(disp$Max, 0L)

    tags$div(
      class = "table-scroll-wrap",
      tags$table(
        class = "table table-sm table-striped",
        tags$thead(tags$tr(lapply(names(disp), tags$th))),
        tags$tbody(
          lapply(seq_len(nrow(disp)), function(i) {
            tags$tr(lapply(disp[i, , drop = FALSE], function(cell) tags$td(as.character(cell))))
          })
        )
      )
    )
  })

  output$run_data_table <- renderDT({
    req(rv$run_data)
    dat <- add_rank_column(rv$run_data)
    datatable(
      dat,
      rownames = FALSE,
      selection = "none",
        options = list(
          dom = "t",
          ordering = FALSE,
          paging = FALSE,
          scrollX = TRUE,
          autoWidth = TRUE,
          fixedColumns = list(leftColumns = 1L)
        ),
      class = "compact",
      callback = dt_callback,
      extensions = c("FixedColumns", "FixedHeader")
    )
  })

  output$status <- renderText({
    rv$status
  })

  output$team_import_status <- renderText({
    rv$team_import_status
  })

  output$download_output <- downloadHandler(
    filename = function() {
      sprintf("%s_hitters_web_output.csv", as.integer(input$season))
    },
    content = function(file) {
      req(valued_hitter_output())
      utils::write.csv(valued_hitter_output(), file, row.names = FALSE, na = "")
    }
  )

  output$download_pitchers <- downloadHandler(
    filename = function() {
      sprintf("%s_pitchers_web_output.csv", as.integer(input$season))
    },
    content = function(file) {
      req(rv$pitcher_data)
      utils::write.csv(rv$pitcher_data, file, row.names = FALSE, na = "")
    }
  )

  output$team_export <- downloadHandler(
    filename = function() {
      sprintf("team_importer_%s.json", format(Sys.Date(), "%Y%m%d"))
    },
    content = function(file) {
      payload <- build_team_import_export_payload()
      txt <- jsonlite::toJSON(payload, auto_unbox = TRUE, pretty = TRUE, null = "null", na = "null")
      writeLines(txt, con = file, useBytes = TRUE)
    },
    contentType = "application/json"
  )

  observeEvent(rv$run_data, {
    if (isTRUE(rv$controls_seeded_from_run_data)) return()
    req(rv$run_data)

    draft_type_label <- get_run_metric_value(rv$run_data, "Draft Type", default = "")
    if (nzchar(draft_type_label)) {
      draft_type_choices <- adp_draft_type_choices
      draft_type_idx <- match(draft_type_label, names(draft_type_choices))
      draft_type_value <- ""
      if (!is.na(draft_type_idx)) {
        draft_type_value <- unname(draft_type_choices[draft_type_idx])
      } else {
        legacy_id <- sub("(?i)^draft\\s*type\\s*", "", draft_type_label, perl = TRUE)
        legacy_id <- trimws(legacy_id)
        if (nzchar(legacy_id) && legacy_id %in% unname(draft_type_choices)) {
          draft_type_value <- legacy_id
        }
      }
      updateSelectInput(session, "adp_draft_type", selected = draft_type_value)
    }

    adp_num_teams_raw <- trimws(get_run_metric_value(rv$run_data, "Number of Teams", default = ""))
    if (nzchar(adp_num_teams_raw) || identical(adp_num_teams_raw, "")) {
      adp_num_teams <- adp_num_teams_raw
      if (tolower(adp_num_teams) %in% c("all teams", "all")) {
        adp_num_teams <- ""
      }
      if (!adp_num_teams %in% c("", "10", "12", "15")) {
        adp_num_teams <- ""
      }
      updateSelectInput(session, "adp_num_teams", selected = adp_num_teams)
    }

    lookback_days <- suppressWarnings(as.integer(get_run_metric_value(rv$run_data, "Lookback Days", default = NA_character_)))
    if (is.na(lookback_days)) {
      date_from <- suppressWarnings(as.Date(get_run_metric_value(rv$run_data, "Date From", default = "")))
      date_to <- suppressWarnings(as.Date(get_run_metric_value(rv$run_data, "Date To", default = "")))
      if (!is.na(date_from) && !is.na(date_to)) {
        lookback_days <- max(1L, as.integer(date_to - date_from))
      }
    }
    if (!is.na(lookback_days) && lookback_days >= 1L) {
      updateNumericInput(session, "adp_lookback_days", value = lookback_days)
    }

    parse_csv_values <- function(x) {
      vals <- trimws(unlist(strsplit(coalesce_chr(x, fallback = ""), ",", fixed = TRUE)))
      vals[nzchar(vals)]
    }

    hitter_cats <- normalize_selected_hitter_categories(parse_csv_values(get_run_metric_value(rv$run_data, "Hitter Categories", default = "")))
    if (length(hitter_cats) > 0) {
      updateCheckboxGroupInput(session, "hitter_categories", selected = hitter_cats)
    }

    metric_to_input <- c(
      PA = "sw_pa",
      HR = "sw_hr",
      SB = "sw_sb",
      AVG = "sw_avg",
      R = "sw_r",
      RBI = "sw_rbi",
      OBP = "sw_obp"
    )
    for (metric_name in names(metric_to_input)) {
      weight_val <- suppressWarnings(as.numeric(get_run_metric_value(rv$run_data, metric_name, default = NA_character_)))
      if (is.finite(weight_val)) {
        updateNumericInput(session, metric_to_input[[metric_name]], value = weight_val)
      }
    }

    pitcher_cats <- tolower(parse_csv_values(get_run_metric_value(rv$run_data, "Pitcher Categories", default = "")))
    pitcher_cats <- pitcher_cats[pitcher_cats %in% unname(pitcher_category_choices)]
    if (length(pitcher_cats) > 0) {
      updateCheckboxGroupInput(session, "pitcher_categories", selected = pitcher_cats)
    }

    rv$controls_seeded_from_run_data <- TRUE
  }, ignoreInit = FALSE)

  # ── SP Streamonator server logic ─────────────────────────────────────────────

  # Load park factors once at startup
  observe({
    if (is.null(rv$stream_park_factors)) {
      rv$stream_park_factors <- load_park_factors()
    }
  })

  # Reactive week range derived from radio button selection
  stream_week <- reactive({
    which_week <- input$stream_which_week %||% "current"
    streamonator_week_range(today = Sys.Date(), which_week = which_week)
  })

  output$stream_week_label <- renderText({
    stream_week()$label
  })

  output$stream_status <- renderText({
    rv$stream_status
  })

  output$stream_skillz_source_note <- renderUI({
    dat <- rv$pitcher_sp_skillz
    if (is.null(dat)) {
      tags$small(class = "text-muted", "SP Skillz not loaded. Run a refresh first.")
    } else {
      season_col <- intersect(c("lookback_season"), names(dat))
      season_val <- if (length(season_col) > 0) dat[[season_col[1]]][1] else "2025"
      tags$small(class = "text-muted",
                 sprintf("Using %s SP Skillz (%d pitchers).", season_val, nrow(dat)))
    }
  })

  # Populate My Pitchers selectize from SP Skillz data
  observe({
    dat <- rv$pitcher_sp_skillz
    if (is.null(dat) || !is.data.frame(dat)) return()
    choices <- sort(unique(dat$player_name[nzchar(dat$player_name %||% "")]))
    updateSelectizeInput(session, "stream_my_pitchers",
                         choices  = choices,
                         server   = TRUE)
  })

  # Fetch probables on button click
  observeEvent(input$stream_refresh, {
    rv$stream_status <- "Fetching probables grid..."
    rv$stream_probables <- NULL

    tryCatch({
      raw    <- fetch_probables_raw()
      parsed <- parse_probables_grid(raw)
      rv$stream_probables <- parsed
      rv$stream_status <- sprintf(
        "Loaded %d starts across %d pitchers. (Fetched %s)",
        nrow(parsed),
        length(unique(parsed$pitcher_name)),
        format(Sys.time(), "%I:%M %p")
      )
    }, error = function(e) {
      rv$stream_status <- paste0("Error fetching probables: ", conditionMessage(e))
    })
  })

  # Reactive: scored Streamonator table filtered to the selected week
  stream_scored <- reactive({
    req(rv$stream_probables)
    wk <- stream_week()
    build_streamonator_table(
      probables_df  = rv$stream_probables,
      sp_skillz_df  = rv$pitcher_sp_skillz,
      park_factors  = rv$stream_park_factors,
      team_rater    = NULL,
      week_start    = wk$start,
      week_end      = wk$end,
      w_sp          = max(0, input$stream_w_sp %||% 1),
      w_tr          = max(0, input$stream_w_tr %||% 1),
      w_pf          = max(0, input$stream_w_pf %||% 1)
    )
  })

  # Helper: render a streamonator DT from a data frame (possibly subset)
  render_stream_dt <- function(df_reactive) {
    renderDT({
      df <- df_reactive()
      if (is.null(df) || nrow(df) == 0) {
        return(datatable(
          data.frame(Message = "No data. Fetch Probables and select a week."),
          rownames = FALSE, options = list(dom = "t")
        ))
      }
      disp <- format_streamonator_for_display(df)
      disp <- add_rank_column(disp)
      disp <- reorder_front_columns(disp, c("rank", "Pitcher", "Team"))
      datatable(
        disp,
        filter    = "none",
        rownames  = FALSE,
        selection = "none",
        options   = build_table_options(disp),
        callback  = dt_callback,
        extensions = c("FixedColumns", "FixedHeader")
      )
    })
  }

  # All Probables table
  output$stream_table_all <- render_stream_dt(stream_scored)

  # 2-Start Probables table
  output$stream_table_2start <- render_stream_dt(reactive({
    df <- stream_scored()
    if (is.null(df) || nrow(df) == 0) return(df)
    df[df$two_start_flag, , drop = FALSE]
  }))

  # My Pitchers: SP Skillz lookup table
  output$stream_my_pitchers_table <- renderDT({
    req(rv$pitcher_sp_skillz)
    selected <- input$stream_my_pitchers
    if (length(selected) == 0) {
      return(datatable(
        data.frame(Message = "Select pitchers on the left to see their SP Skillz."),
        rownames = FALSE, options = list(dom = "t")
      ))
    }

    wk  <- stream_week()
    dat <- build_my_pitchers_table(
      my_pitcher_names = selected,
      sp_skillz_df     = rv$pitcher_sp_skillz,
      probables_df     = rv$stream_probables,
      week_start       = wk$start,
      week_end         = wk$end
    )

    if (is.null(dat) || nrow(dat) == 0) {
      return(datatable(
        data.frame(Message = "No SP Skillz data found for selected pitchers."),
        rownames = FALSE, options = list(dom = "t")
      ))
    }

    col_map <- c(
      player_name                 = "Name",
      team                        = "Team",
      gs                          = "GS",
      ip                          = "IP",
      siera                       = "SIERA",
      xfip                        = "xFIP",
      k_minus_bb_pct              = "K-BB%",
      contact_pct                 = "Contact%",
      csw_pct                     = "CSW%",
      stuff_plus                  = "Stuff+",
      pitching_plus               = "Pitching+",
      sp_skillz_score_stabilized  = "SP Skillz Score",
      sp_skillz_rank_stabilized   = "SP Skillz Rank",
      sp_skillz_index             = "SP Skillz Index",
      starts_this_week            = "Starts This Week"
    )
    keep <- intersect(names(col_map), names(dat))
    disp <- dat[, keep, drop = FALSE]

    numeric_round_map <- c(
      ip = 1L, siera = 3L, xfip = 3L,
      k_minus_bb_pct = 2L, contact_pct = 2L, csw_pct = 2L,
      stuff_plus = 2L, pitching_plus = 2L,
      sp_skillz_score_stabilized = 2L,
      sp_skillz_index = 1L
    )
    for (nm in names(numeric_round_map)) {
      if (nm %in% names(disp)) {
        disp[[nm]] <- round(suppressWarnings(as.numeric(disp[[nm]])),
                            digits = numeric_round_map[[nm]])
      }
    }

    names(disp) <- unname(col_map[keep])
    datatable(
      disp,
      filter    = "none",
      rownames  = FALSE,
      selection = "none",
      options   = build_table_options(disp),
      callback  = dt_callback,
      extensions = c("FixedColumns", "FixedHeader")
    )
  })

  # My Pitchers: JSON export
  output$stream_my_export <- downloadHandler(
    filename = function() {
      sprintf("my_pitchers_%s.json", format(Sys.Date(), "%Y%m%d"))
    },
    content = function(file) {
      selected <- input$stream_my_pitchers %||% character(0)
      jsonlite::write_json(list(pitchers = as.list(selected)), file, pretty = TRUE)
    }
  )

  # My Pitchers: JSON import
  observeEvent(input$stream_my_import, {
    req(input$stream_my_import)
    tryCatch({
      imported <- jsonlite::fromJSON(input$stream_my_import$datapath)
      names_vec <- as.character(imported$pitchers %||% character(0))
      names_vec <- names_vec[nzchar(names_vec)]
      if (length(names_vec) > 0) {
        updateSelectizeInput(session, "stream_my_pitchers", selected = names_vec)
      }
    }, error = function(e) {
      showNotification(paste("Import failed:", conditionMessage(e)),
                       type = "error", duration = 5)
    })
  })
}

shinyApp(ui, server)
